"use client";

import { useState } from "react";
import { Store, Copy, ExternalLink, Loader2, Share2, Check } from "lucide-react";
import { toast } from "react-hot-toast";
import { generateAdminStoreSlug } from "./actions";

interface AdminStoreCardProps {
  initialSlug: string | null;
  adminName: string;
}

export default function AdminStoreCard({ initialSlug, adminName }: AdminStoreCardProps) {
  const [slug, setSlug] = useState(initialSlug);
  const [isGenerating, setIsGenerating] = useState(false);
  const [copied, setCopied] = useState(false);

  const storeUrl = typeof window !== "undefined" ? `${window.location.origin}/store/${slug}` : "";

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      const res = await generateAdminStoreSlug();
      if (res.success && res.slug) {
        setSlug(res.slug);
        toast.success("Store slug generated!");
      } else {
        toast.error(res.error || "Failed to generate slug");
      }
    } catch (error) {
      toast.error("Something went wrong");
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(storeUrl);
    setCopied(true);
    toast.success("Link copied to clipboard!");
    setTimeout(() => setCopied(false), 2000);
  };

  if (!slug) {
    return (
      <div className="glass rounded-2xl p-6 border border-border/50 shadow-sm flex flex-col items-center justify-center text-center space-y-4">
        <div className="p-3 bg-primary/10 rounded-full">
          <Store className="h-8 w-8 text-primary" />
        </div>
        <div>
          <h3 className="font-bold text-lg">Your Admin Store</h3>
          <p className="text-sm text-muted-foreground">You haven't set up your shareable store link yet.</p>
        </div>
        <button
          disabled={isGenerating}
          onClick={handleGenerate}
          className="px-6 py-2 bg-primary text-primary-foreground rounded-xl font-bold flex items-center space-x-2 hover:brightness-110 transition-all disabled:opacity-70"
        >
          {isGenerating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Store className="h-4 w-4" />}
          <span>Generate Store Link</span>
        </button>
      </div>
    );
  }

  return (
    <div className="glass rounded-2xl p-6 border border-border/50 shadow-sm flex flex-col space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="p-2 bg-primary/10 rounded-lg text-primary">
            <Share2 className="h-5 w-5" />
          </div>
          <h3 className="font-bold">Your Shareable Store</h3>
        </div>
        <a 
          href={`/store/${slug}`} 
          target="_blank" 
          className="p-2 hover:bg-muted rounded-lg text-muted-foreground transition-colors"
          title="Preview Store"
        >
          <ExternalLink className="h-4 w-4" />
        </a>
      </div>

      <div className="space-y-2">
        <p className="text-xs text-muted-foreground uppercase font-black tracking-widest">Store Link</p>
        <div className="flex items-center space-x-2 bg-muted/30 p-3 rounded-xl border border-border">
          <code className="text-xs font-mono truncate flex-1">{storeUrl}</code>
          <button 
            onClick={copyToClipboard}
            className="p-2 hover:bg-background rounded-lg transition-all active:scale-95 text-primary"
          >
            {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
          </button>
        </div>
      </div>

      <p className="text-[10px] text-muted-foreground italic">
        Share this link with customers to allow them to buy data directly from you without needing an account.
      </p>
    </div>
  );
}

"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function generateAdminStoreSlug() {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") {
    return { success: false, error: "Unauthorized" };
  }

  try {
    const user = await prisma.user.findUnique({
      where: { id: (session.user as any).id }
    });

    if (!user) return { success: false, error: "User not found" };
    if (user.storeSlug) return { success: true, slug: user.storeSlug };

    const slug = (user.name || "admin").toLowerCase().replace(/[^a-z0-9]/g, "-") + "-" + Math.floor(Math.random() * 1000);

    await prisma.user.update({
      where: { id: user.id },
      data: { storeSlug: slug }
    });

    revalidatePath("/admin");
    revalidatePath("/admin/store");
    return { success: true, slug };
  } catch (error) {
    return { success: false, error: "Failed to generate slug" };
  }
}

export async function deleteAdminStore() {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") {
    return { success: false, error: "Unauthorized" };
  }

  try {
    await prisma.user.update({
      where: { id: (session.user as any).id },
      data: { storeSlug: null }
    });

    revalidatePath("/admin");
    revalidatePath("/admin/store");
    return { success: true };
  } catch (error) {
    return { success: false, error: "Failed to delete store" };
  }
}

export async function updateStoreSlug(newSlug: string) {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") {
    return { success: false, error: "Unauthorized" };
  }

  const sanitized = newSlug.toLowerCase().replace(/[^a-z0-9-]/g, "-").replace(/--+/g, "-").replace(/^-|-$/g, "");
  if (sanitized.length < 3) return { success: false, error: "Slug must be at least 3 characters" };

  try {
    const existing = await prisma.user.findUnique({ where: { storeSlug: sanitized } });
    if (existing && existing.id !== (session.user as any).id) {
      return { success: false, error: "That slug is already taken" };
    }

    await prisma.user.update({
      where: { id: (session.user as any).id },
      data: { storeSlug: sanitized }
    });

    revalidatePath("/admin/store");
    revalidatePath("/admin");
    return { success: true, slug: sanitized };
  } catch (error) {
    return { success: false, error: "Failed to update slug" };
  }
}

"use client";

import { useState } from "react";
import { sendBroadcast } from "./actions";
import { toast } from "react-hot-toast";
import { Megaphone, Send, Link as LinkIcon, AlertCircle } from "lucide-react";

export function BroadcastForm() {
    const [formData, setFormData] = useState({ title: "", message: "", url: "" });
    const [isSending, setIsSending] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isSending) return;

        if (!confirm("Are you sure you want to send this notification to ALL users?")) return;

        setIsSending(true);
        const result = await sendBroadcast(formData);

        if (result.success) {
            toast.success("Broadcast sent successfully!");
            setFormData({ title: "", message: "", url: "" });
        } else {
            toast.error(result.error || "Failed to send broadcast");
        }
        setIsSending(false);
    };

    return (
        <div className="max-w-2xl space-y-6 animate-in">
            <div className="bg-blue-50 border border-blue-100 p-6 rounded-3xl flex items-start space-x-4">
                <div className="p-2 bg-blue-100 rounded-xl text-blue-600">
