"use client";

import { useState } from "react";
import { formatCurrency, cn } from "@/lib/utils";
import { CheckCircle, XCircle, Clock, Search, RefreshCcw, User, Package, Phone, Hash, ShoppingBag, Calendar } from "lucide-react";
import { RefreshOrderButton } from "@/components/RefreshOrderButton";
import Link from "next/link";
import { retryOrder } from "../users/actions";
import { toast } from "react-hot-toast";

interface Order {
  id: string;
  userId: string | null;
  bundleId: string;
  phone: string;
  amount: any;
  status: string;
  paymentRef: string | null;
  paymentMethod: string;
  supplierOrderId: string | null;
  supplierStatus: string | null;
  agentId: string | null;
  commissionEarned: any;
  failureReason: string | null;
  createdAt: any;
  user: { name: string | null; email: string | null } | null;
  bundle: { network: string; size: string };
}

export function OrdersClient({ initialOrders }: { initialOrders: Order[] }) {
  const [activeTab, setActiveTab] = useState("ALL");
  const [searchTerm, setSearchTerm] = useState("");
  const [isProcessing, setIsProcessing] = useState<string | null>(null);

  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [debitOption, setDebitOption] = useState<"CUSTOMER" | "ADMIN" | "NONE">("CUSTOMER");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const executeRetry = async () => {
    if (!selectedOrder) return;
    setIsSubmitting(true);
    setIsProcessing(selectedOrder.id);
    try {
      const res = await retryOrder(selectedOrder.id, debitOption);
      if (res.success) {
        toast.success(res.message || "Order queued for resubmission!");
        window.location.reload();
      } else {
        toast.error(res.error || "Failed to replace order");
      }
    } catch (err: any) {
      toast.error(err.message || "An error occurred");
    } finally {
      setIsSubmitting(false);
      setIsProcessing(null);
      setSelectedOrder(null);
    }
  };

  const statusIcons: Record<string, any> = {
    PENDING: { color: "text-yellow-600 bg-yellow-100 border-yellow-200", icon: Clock },
    PROCESSING: { color: "text-blue-600 bg-blue-100 border-blue-200", icon: Clock },
    COMPLETED: { color: "text-green-600 bg-green-100 border-green-200", icon: CheckCircle },
    FAILED: { color: "text-red-600 bg-red-100 border-red-200", icon: XCircle },
  };

  const tabs = [
    { label: "All Orders", value: "ALL" },
    { label: "Pending", value: "PENDING" },
    { label: "Processing", value: "PROCESSING" },
    { label: "Completed", value: "COMPLETED" },
    { label: "Failed", value: "FAILED" },
    { label: "Failed Guests", value: "FAILED_GUEST" },
  ];

  const filteredOrders = initialOrders.filter(order => {
    let matchesTab = false;
    if (activeTab === "ALL") {
      matchesTab = true;
    } else if (activeTab === "FAILED_GUEST") {
      matchesTab = order.status === "FAILED" && !order.userId;
    } else {
      matchesTab = order.status === activeTab;
    }

    const matchesSearch = 
      order.phone.includes(searchTerm) || 
      order.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.paymentRef?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.user?.name?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesTab && matchesSearch;
  });

  return (
    <div className="space-y-6">
      {/* Tabs & Search */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-card p-2 rounded-2xl border shadow-sm">
        <div className="flex space-x-1 overflow-x-auto no-scrollbar w-full md:w-auto">
          {tabs.map(tab => (
            <button
              key={tab.value}
              onClick={() => setActiveTab(tab.value)}
              className={cn(
                "px-4 py-2 rounded-xl text-sm font-bold transition-all whitespace-nowrap",
                activeTab === tab.value
                  ? "bg-primary text-primary-foreground shadow-md shadow-primary/20"
                  : "text-muted-foreground hover:bg-muted"
              )}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="relative w-full md:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <input
            type="text"
            placeholder="Search orders..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-muted/50 border-none rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary/20 transition-all"
          />
        </div>
      </div>

      {/* Orders List */}
      <div className="space-y-4">
        {filteredOrders.length > 0 ? (
          filteredOrders.map((order) => {
            const StatusIcon = statusIcons[order.status]?.icon || Clock;
            const statusColor = statusIcons[order.status]?.color || "bg-gray-100 text-gray-500 border-gray-200";

            return (
              <div 
                key={order.id} 
                className="group bg-card border rounded-2xl p-4 md:p-6 hover:shadow-xl hover:border-primary/20 transition-all duration-300 animate-in fade-in slide-in-from-bottom-2"
              >
                <div className="flex flex-col md:grid md:grid-cols-12 gap-6 items-start md:items-center">
                  
                  {/* Info Column */}
                  <div className="col-span-3 space-y-1 w-full">
                    <div className="flex items-center space-x-2">
                        <Hash className="h-3 w-3 text-muted-foreground" />
                        <span className="text-xs font-black font-mono uppercase text-muted-foreground">#{order.id.substring(0, 8)}</span>
                    </div>
                    <div className="flex items-center space-x-2">
                        <User className="h-4 w-4 text-primary" />
                        <p className="font-bold text-sm truncate">{order.user?.name || "Guest Checkout"}</p>
                        {!order.userId && (
                            <span className="bg-red-50 text-red-600 dark:bg-red-950/20 dark:text-red-400 text-[8px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-widest border border-red-100 dark:border-red-900/30">
                              Guest
                            </span>
                        )}
                    </div>
                    <p className="text-xs text-muted-foreground pl-6 truncate">{order.user?.email || order.paymentRef || "No Email"}</p>
                    <div className="flex items-center space-x-2 pl-6">
                        <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                        <span className="text-xs text-muted-foreground font-mono">
                            {new Date(order.createdAt).toLocaleDateString('en-GB')} {new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })}
                        </span>
                    </div>
                  </div>

                  {/* Bundle Column */}
                  <div className="col-span-3 space-y-1 w-full">
                    <div className="flex items-center space-x-2">
                        <Package className="h-4 w-4 text-primary" />
                        <p className="font-bold text-sm">
                            <span className="text-primary">{order.bundle?.network || "Data"}</span> {order.bundle?.size || "Bundle"}
                        </p>
                    </div>
                    <div className="flex items-center space-x-2 pl-6">
                        <Phone className="h-3 w-3 text-muted-foreground" />
                        <p className="text-xs font-black font-mono">{order.phone}</p>
                    </div>
                  </div>

                  {/* Amount Column */}
                  <div className="col-span-2 w-full">
                    <p className="text-xs font-black uppercase text-muted-foreground tracking-widest mb-1">Price Paid</p>
                    <p className="text-xl font-black font-outfit text-primary">{formatCurrency(order.amount)}</p>
                  </div>

                  {/* Status Column */}
                  <div className="col-span-2 w-full">
                    <div className={cn(
                        "inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-full text-xs font-black uppercase tracking-wider border",
                        statusColor
                    )}>
                        <StatusIcon className="h-3 w-3" />
                        <span>{order.supplierStatus || order.status}</span>
                    </div>
                    {order.failureReason && (
                        <p className="text-xs text-red-500 mt-2 font-bold leading-tight">Reason: {order.failureReason}</p>
                    )}
                  </div>

                  {/* Action Column */}
                  <div className="col-span-2 w-full flex md:justify-end items-center space-x-3">
                     {(order.status === "PROCESSING" || order.status === "PENDING") && (
                        <div className="relative group">
                             <RefreshOrderButton orderId={order.id} />
                             <span className="absolute -top-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-all pointer-events-none whitespace-nowrap font-black">TRACK LIVE</span>
                        </div>
                     )}
                     {order.status === "FAILED" && (
                        <button
                          onClick={() => {
                            setSelectedOrder(order);
                            setDebitOption(order.userId ? "CUSTOMER" : "NONE");
                          }}
                          disabled={isProcessing === order.id}
                          className="flex items-center space-x-1 px-3 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-bold transition-all shadow-sm disabled:opacity-50"
                          title="Retry/replace order with supplier"
                        >
                          <RefreshCcw className={cn("h-3.5 w-3.5", isProcessing === order.id && "animate-spin")} />
                          <span>Replace</span>
                        </button>
                     )}
                     <Link 
                        href={`/admin/orders/${order.id}`}
                        className="p-3 bg-muted hover:bg-primary hover:text-primary-foreground rounded-xl transition-all"
                     >
                        <ArrowRight className="h-4 w-4" />
                     </Link>
                  </div>
                </div>
              </div>
            )
          })
        ) : (
          <div className="py-20 text-center glass border-dashed rounded-3xl">
             <ShoppingBag className="h-12 w-12 mx-auto text-muted-foreground/30 mb-4" />
             <p className="text-muted-foreground font-bold">No {activeTab.toLowerCase()} orders found matching your criteria.</p>
          </div>
        )}
      </div>

      {/* Debit Option Modal */}
      {selectedOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-background w-full max-w-md rounded-2xl shadow-2xl border border-border overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-border flex items-center justify-between">
              <h2 className="text-xl font-bold font-outfit text-foreground">Replace/Retry Order</h2>
              <button onClick={() => setSelectedOrder(null)} className="p-2 hover:bg-muted rounded-full transition-colors">
                <XCircle className="h-5 w-5 text-muted-foreground" />
              </button>
            </div>
            
            <div className="p-6 space-y-4">
              <div className="bg-muted/30 p-4 rounded-xl space-y-2 text-sm text-foreground">
                <p><strong>Order ID:</strong> #{selectedOrder.id.substring(0, 8)}</p>
                <p><strong>Bundle:</strong> {selectedOrder.bundle?.network} {selectedOrder.bundle?.size}</p>
                <p><strong>Phone:</strong> {selectedOrder.phone}</p>
                <p><strong>Amount:</strong> {formatCurrency(selectedOrder.amount)}</p>
                <p><strong>Customer:</strong> {selectedOrder.user?.name || "Guest Checkout"}</p>
              </div>

              <div className="space-y-3">
                <label className="text-xs font-black uppercase tracking-widest text-muted-foreground block">Choose Account to Debit</label>
                
                {selectedOrder.userId && (
                  <label className="flex items-start space-x-3 p-3 rounded-xl border hover:bg-muted/20 cursor-pointer transition-all">
                    <input 
                      type="radio" 
                      name="debitOption" 
                      value="CUSTOMER" 
                      checked={debitOption === "CUSTOMER"}
                      onChange={() => setDebitOption("CUSTOMER")}
                      className="mt-1 h-4 w-4 text-primary focus:ring-primary"
                    />
                    <div className="text-sm">
                      <p className="font-bold text-foreground">Debit Customer's Wallet</p>
                      <p className="text-xs text-muted-foreground">User was refunded to wallet on failure. This charges them again.</p>
                    </div>
                  </label>
                )}

                <label className="flex items-start space-x-3 p-3 rounded-xl border hover:bg-muted/20 cursor-pointer transition-all">
                  <input 
                    type="radio" 
                    name="debitOption" 
                    value="ADMIN" 
                    checked={debitOption === "ADMIN"}
                    onChange={() => setDebitOption("ADMIN")}
                    className="mt-1 h-4 w-4 text-primary focus:ring-primary"
                  />
                  <div className="text-sm">
                    <p className="font-bold text-foreground">Debit Admin's Wallet</p>
                    <p className="text-xs text-muted-foreground">Deducts the cost from your admin platform wallet balance.</p>
                  </div>
                </label>

                <label className="flex items-start space-x-3 p-3 rounded-xl border hover:bg-muted/20 cursor-pointer transition-all">
                  <input 
                    type="radio" 
                    name="debitOption" 
                    value="NONE" 
                    checked={debitOption === "NONE"}
                    onChange={() => setDebitOption("NONE")}
                    className="mt-1 h-4 w-4 text-primary focus:ring-primary"
                  />
                  <div className="text-sm">
                    <p className="font-bold text-foreground">No Wallet Deduction</p>
                    <p className="text-xs text-muted-foreground">Does not debit any wallet (suitable for guest checkouts or cash orders).</p>
                  </div>
                </label>
              </div>

              <div className="pt-4 flex space-x-3">
                <button
                  onClick={() => setSelectedOrder(null)}
                  className="flex-1 py-3 border rounded-xl font-bold hover:bg-muted active:scale-95 transition-all text-sm text-foreground bg-transparent"
                >
                  Cancel
                </button>
                <button
                  disabled={isSubmitting}
                  onClick={executeRetry}
                  className="flex-1 py-3 bg-primary text-primary-foreground font-bold rounded-xl hover:brightness-110 active:scale-95 transition-all text-sm flex items-center justify-center space-x-2"
                >
                  <span>{isSubmitting ? "Processing..." : "Confirm Replace"}</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function ArrowRight({ className }: { className?: string }) {
    return (
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg>
    );
}

import prisma from "@/lib/prisma";
export const dynamic = "force-dynamic";

import { OrdersClient } from "./OrdersClient";
import DateFilter from "../DateFilter";
import { AutoRefreshToggle } from "@/components/AutoRefreshToggle";
import { Suspense } from "react";

export default async function AdminOrdersPage({ searchParams }: { searchParams: Promise<{ date?: string, endDate?: string }> }) {
  const { date: startDateParam, endDate: endDateParam } = await searchParams;
  
  const today = new Date().toISOString().split('T')[0];
  const filterDate = startDateParam || today;
  const filterEndDate = endDateParam || filterDate;

  const startDate = new Date(filterDate);
  startDate.setHours(0, 0, 0, 0);
  
  const endDate = new Date(filterEndDate);
  endDate.setHours(23, 59, 59, 999);

  const where: any = {
    createdAt: {
        gte: startDate,
        lte: endDate
    }
  };

  const orders = await prisma.order.findMany({
    where,
    select: {
      id: true,
      userId: true,
      status: true,
      phone: true,
      amount: true,
      createdAt: true,
      paymentMethod: true,
      supplierStatus: true,
      supplierOrderId: true,
      commissionEarned: true,
      failureReason: true,
      user: {
        select: { id: true, name: true, email: true, role: true }
      },
      bundle: {
        select: { network: true, size: true, supplierPrice: true }
      }
    },
    orderBy: { createdAt: "desc" },
  });

  return (
    <div className="space-y-8 animate-in pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <div className="flex items-center space-x-3">
            <h1 className="text-3xl font-bold font-outfit">Platform Orders</h1>
            <span className="bg-primary/10 text-primary px-3 py-1 rounded-full text-xs font-black uppercase tracking-widest border border-primary/20">
                {orders.length} Orders
            </span>
          </div>
          <p className="text-muted-foreground">
            {filterDate === filterEndDate ? `Tracking for ${filterDate}` : `Range: ${filterDate} to ${filterEndDate}`}
          </p>
        </div>
        <div className="flex flex-col md:flex-row items-stretch md:items-center gap-4 w-full md:w-auto">
            <Suspense fallback={<div>Loading filters...</div>}>
                <AutoRefreshToggle />
                <DateFilter />
            </Suspense>
        </div>
      </div>

      <OrdersClient initialOrders={JSON.parse(JSON.stringify(orders))} />
    </div>
  );
}

import prisma from "@/lib/prisma";
import { Suspense } from "react";
export const dynamic = "force-dynamic";

import { formatCurrency } from "@/lib/utils";
import { Users, ShoppingBag, DollarSign, Zap, Wallet, Settings, Trophy, TrendingUp, Megaphone } from "lucide-react";
import Link from "next/link";
import { getActiveSupplier } from "@/lib/suppliers";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import AdminStoreCard from "./AdminStoreCard";
import DateFilter from "./DateFilter";

export default async function AdminDashboard({ searchParams }: { searchParams: Promise<{ date?: string, endDate?: string }> }) {
  const { date: startDateParam, endDate: endDateParam } = await searchParams;
  const session = await getServerSession(authOptions);
  
  // Handle Date Range Filtering
  const today = new Date().toISOString().split('T')[0];
  const startDateStr = startDateParam || today;
  const endDateStr = endDateParam || startDateStr; // Default to single day if endDate is missing
  
  const startDate = new Date(startDateStr);
  startDate.setHours(0, 0, 0, 0);
  
  const endDate = new Date(endDateStr);
  endDate.setHours(23, 59, 59, 999);

  // H1 FIX: Fetch supplier balance in parallel with DB queries, not serially after them.
  // If the supplier API is slow, this was blocking the entire admin page for 5-15 seconds.
  const supplierPromise = getActiveSupplier().then(s => s.fetchBalance()).catch(() => 0);

  const [
    userCount, 
    orderCount, 
    totalRevenue, 
    pendingPayouts, 
    allOrdersCount,
    completedOrders,
    failedOrders,
    allPendingOrders,
    totalUserBalance,
    adminUser,
    // C1 FIX: Use aggregates instead of findMany + JS reduce.
    // The old code fetched ALL completed orders into memory just to sum them —
    // this caused 30+ second load times and OOM at scale.
    totalProfitAgg,
    rangeProfitAgg,
    supplierBalance
  ] = await Promise.all([
    prisma.user.count(),
    prisma.order.count({
      where: {
        createdAt: {
          gte: startDate,
          lte: endDate
        }
      }
    }),
    prisma.order.aggregate({
      _sum: { amount: true },
      where: { 
        status: "COMPLETED",
        createdAt: {
          gte: startDate,
          lte: endDate
        }
      }
    }),
    prisma.withdrawal.count({ where: { status: "PENDING" } }),
    prisma.order.count(),
    prisma.order.count({ where: { status: "COMPLETED" } }),
    prisma.order.count({ where: { status: "FAILED" } }),
    prisma.order.count({ where: { status: "PENDING" } }),
    prisma.user.aggregate({ _sum: { balance: true } }),
    prisma.user.findUnique({ where: { id: (session?.user as any)?.id } }),
    // C1 FIX: Aggregate for total profit (all-time completed)
    prisma.order.aggregate({
      _sum: { amount: true, commissionEarned: true },
      where: { status: "COMPLETED" }
    }),
    // C1 FIX: Aggregate for range profit (date-filtered completed)
    prisma.order.aggregate({
      _sum: { amount: true, commissionEarned: true },
      where: { 
        status: "COMPLETED",
        createdAt: { gte: startDate, lte: endDate }
      }
    }),
    // H1 FIX: Supplier balance fetched in parallel instead of after all DB queries
    supplierPromise
  ]);

  // C1 FIX: Compute profit from the aggregates. Since we cannot aggregate
  // (amount - bundle.supplierPrice) across a relation in Prisma without a raw query,
  // we approximate profit as (revenue - commissions). This is accurate for the platform's
  // share; for a precise cost-based profit, store supplierCost on the Order model.
  const totalRevAll = Number(totalProfitAgg._sum.amount || 0);
  const totalCommAll = Number(totalProfitAgg._sum.commissionEarned || 0);
  const totalProfit = totalRevAll - totalCommAll;

  const rangeRevAll = Number(rangeProfitAgg._sum.amount || 0);
  const rangeCommAll = Number(rangeProfitAgg._sum.commissionEarned || 0);
  const rangeProfit = rangeRevAll - rangeCommAll;

  const stats = [
    { name: "Total Users", value: userCount, icon: Users, color: "text-blue-500 bg-blue-100", href: "/admin/users" },
    { name: "Users Balance", value: formatCurrency((totalUserBalance._sum.balance || 0).toString()), icon: Wallet, color: "text-indigo-500 bg-indigo-100", href: "/admin/users" },
    { name: "My Balance", value: formatCurrency((adminUser?.balance || 0).toString()), icon: DollarSign, color: "text-emerald-500 bg-emerald-100", href: "/dashboard" },
    { name: "Supplier Wallet", value: formatCurrency(supplierBalance.toString()), icon: Zap, color: "text-purple-500 bg-purple-100", href: "/admin/settings" },
    { name: "Total Orders", value: allOrdersCount, icon: ShoppingBag, color: "text-slate-500 bg-slate-100", href: "/admin/orders" },
    { name: "Completed", value: completedOrders, icon: ShoppingBag, color: "text-green-500 bg-green-100", href: "/admin/orders?status=COMPLETED" },
    { name: "Pending", value: allPendingOrders, icon: ShoppingBag, color: "text-orange-500 bg-orange-100", href: "/admin/orders?status=PENDING" },
    { name: "Failed", value: failedOrders, icon: ShoppingBag, color: "text-red-500 bg-red-100", href: "/admin/orders?status=FAILED" },
    { name: "Profit (Range)", value: formatCurrency(rangeProfit.toString()), icon: TrendingUp, color: "text-emerald-600 bg-emerald-50", href: "/admin/sales" },
    { name: "Revenue (Range)", value: formatCurrency((totalRevenue._sum.amount || 0).toString()), icon: DollarSign, color: "text-green-400 bg-green-50", href: "/admin/sales" },
    { name: "Orders (Range)", value: orderCount, icon: ShoppingBag, color: "text-orange-400 bg-orange-50", href: "/admin/orders" },
    { name: "Total Profit", value: formatCurrency(totalProfit.toString()), icon: Trophy, color: "text-yellow-600 bg-yellow-50", href: "/admin/sales" },
  ];

  // C1 FIX: Replace the N+1 ranking query (5 individual findUnique calls)
  // with a single batched findMany lookup.
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

  const rankingData = await prisma.order.groupBy({
    by: ['userId'],
    _sum: { amount: true },
    where: {
      status: "COMPLETED",
      createdAt: { gte: sevenDaysAgo },
      userId: { not: null }
    },
    orderBy: {
      _sum: { amount: 'desc' }
    },
    take: 5
  });

  // Batch: fetch all 5 users in a single query instead of 5 individual ones
  const rankedUserIds = rankingData.map(r => r.userId).filter(Boolean) as string[];
  const rankedUsers = rankedUserIds.length > 0
    ? await prisma.user.findMany({
        where: { id: { in: rankedUserIds } },
        select: { id: true, name: true, image: true, email: true }
      })
    : [];
  const rankedUserMap = new Map(rankedUsers.map(u => [u.id, u]));

  const weeklyRanking = rankingData.map(item => ({
    ...item,
    user: rankedUserMap.get(item.userId || "") || null
  }));


  return (
    <div className="space-y-8 animate-in">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold font-outfit">Dashboard Overview</h1>
          <p className="text-muted-foreground">
            {startDateStr === endDateStr 
              ? `Stats for ${startDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}`
              : `Range: ${startDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} - ${endDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}`
            }
          </p>
        </div>
        <Suspense fallback={<div className="h-10 w-32 bg-muted animate-pulse rounded-2xl" />}>
          <DateFilter />
        </Suspense>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-6 gap-6">
        {stats.map((stat) => (
          <Link 
            key={stat.name} 
            href={stat.href}
            className="glass rounded-2xl p-6 border border-border/50 shadow-sm hover:scale-105 hover:border-primary/30 transition-all cursor-pointer group"
          >
            <div className="flex items-center justify-between mb-4">
              <div className={`p-2 rounded-lg ${stat.color} group-hover:scale-110 transition-transform`}>
                <stat.icon className="h-6 w-6" />
              </div>
            </div>
            <p className="text-sm font-medium text-muted-foreground">{stat.name}</p>
            <h3 className="text-2xl font-black font-outfit mt-1">{stat.value}</h3>
          </Link>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
            <AdminStoreCard initialSlug={adminUser?.storeSlug || null} adminName={adminUser?.name || "Admin"} />
        </div>
        
        <div className="lg:col-span-1 glass rounded-2xl p-6 border border-border/50 shadow-sm flex flex-col justify-between">
          <div>
            <h2 className="font-bold mb-4 flex items-center space-x-2">
                <Settings className="h-4 w-4 text-muted-foreground" />
                <span>Quick Links</span>
            </h2>
            <div className="grid grid-cols-2 gap-4">
                <Link href="/admin/pricing" className="p-4 rounded-xl bg-primary text-primary-foreground hover:brightness-110 transition-all text-center flex flex-col items-center justify-center space-y-2">
                    <DollarSign className="h-5 w-5" />
                    <p className="text-xs font-black uppercase tracking-widest">Set Prices</p>
                </Link>
                <Link href="/admin/broadcast" className="p-4 rounded-xl bg-orange-600 text-white hover:brightness-110 transition-all text-center flex flex-col items-center justify-center space-y-2">
                    <Megaphone className="h-5 w-5" />
                    <p className="text-xs font-black uppercase tracking-widest">Broadcast</p>
                </Link>
                <Link href="/admin/users" className="p-4 rounded-xl bg-secondary hover:bg-muted transition-all text-center flex flex-col items-center justify-center space-y-2">
                    <Users className="h-5 w-5" />
                    <p className="text-xs font-black uppercase tracking-widest">Manage Users</p>
                </Link>
                <Link href="/admin/wallet" className="p-4 rounded-xl bg-secondary hover:bg-muted transition-all text-center flex flex-col items-center justify-center space-y-2">
                    <Wallet className="h-5 w-5" />
                    <p className="text-xs font-black uppercase tracking-widest">Manage Wallet</p>
                </Link>
                <Link href="/admin/settings" className="p-4 rounded-xl bg-secondary hover:bg-muted transition-all text-center flex flex-col items-center justify-center space-y-2">
                    <Settings className="h-5 w-5" />
                    <p className="text-xs font-black uppercase tracking-widest">API Keys</p>
                </Link>
            </div>
          </div>
        </div>

        <div className="lg:col-span-1 glass rounded-2xl p-6 border border-border/50 shadow-sm">
            <div className="flex items-center justify-between mb-6">
                <h2 className="font-bold flex items-center space-x-2">
                    <Trophy className="h-5 w-5 text-yellow-500" />
                    <span>Weekly Ranking</span>
                </h2>
                <TrendingUp className="h-4 w-4 text-green-500" />
            </div>

            <div className="space-y-4">
                {weeklyRanking.length > 0 ? weeklyRanking.map((rank, index) => (
                    <div key={index} className="flex items-center justify-between p-3 rounded-xl bg-muted/30 border border-border/10">
                        <div className="flex items-center space-x-3">
                            <div className={`h-8 w-8 rounded-full flex items-center justify-center text-sm font-black ${
                                index === 0 ? "bg-yellow-100 text-yellow-700" : 
                                index === 1 ? "bg-slate-100 text-slate-700" :
                                index === 2 ? "bg-orange-100 text-orange-700" :
                                "bg-muted text-muted-foreground"
                            }`}>
                                {index + 1}
                            </div>
                            <div>
                                <p className="text-sm font-bold truncate max-w-[120px]">{rank.user?.name || rank.user?.email || "Unknown Agent"}</p>
                                <p className="text-xs text-muted-foreground uppercase tracking-tight">Top Performer</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <p className="text-sm font-black text-primary">{formatCurrency((rank._sum.amount || 0).toString())}</p>
                            <div className="w-16 h-1 bg-muted rounded-full mt-1 overflow-hidden">
                                <div 
                                    className="h-full bg-primary" 
                                    style={{ width: `${(Number(rank._sum.amount) / Number(weeklyRanking[0]._sum.amount)) * 100}%` }}
                                />
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-8 text-muted-foreground">
                        <p className="text-sm italic">No sales in the last 7 days</p>
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
}

