"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

export async function getSalesReport(startDate?: Date, endDate?: Date) {
  const session = await getServerSession(authOptions);
  if ((session?.user as any)?.role !== "ADMIN") {
    throw new Error("Unauthorized");
  }

  const where: any = {
    status: { in: ["PROCESSING", "COMPLETED"] },
  };

  if (startDate || endDate) {
    where.createdAt = {};
    if (startDate) {
      where.createdAt.gte = startDate;
    }
    if (endDate) {
      // Set to end of day
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      where.createdAt.lte = end;
    }
  }

  const orders = await prisma.order.findMany({
    where,
    include: {
      bundle: true,
      user: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  const stats = orders.reduce(
    (acc, order) => {
      const revenue = Number(order.amount);
      const commission = Number(order.commissionEarned || 0);
      const cost = Number(order.bundle?.supplierPrice || 0);
      const profit = revenue - commission - cost;

      return {
        totalRevenue: acc.totalRevenue + revenue,
        totalCost: acc.totalCost + cost,
        totalProfit: acc.totalProfit + profit,
        orderCount: acc.orderCount + 1,
      };
    },
    { totalRevenue: 0, totalCost: 0, totalProfit: 0, orderCount: 0 }
  );

  return { orders, stats };
}

"use client";

import { useState } from "react";
import { Store, Copy, ExternalLink, Loader2, Share2, Check, Trash2, Edit3, Save, X, RefreshCw, ShoppingBag } from "lucide-react";
import { toast } from "react-hot-toast";
import { generateAdminStoreSlug, deleteAdminStore, updateStoreSlug } from "../actions";
import { cn } from "@/lib/utils";

interface StoreManagerProps {
  initialSlug: string | null;
  adminName: string;
  bundles: any[];
  storeOrderCount: number;
}

export default function StoreManager({ initialSlug, adminName, bundles, storeOrderCount }: StoreManagerProps) {
  const [slug, setSlug] = useState(initialSlug);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isEditingSlug, setIsEditingSlug] = useState(false);
  const [slugInput, setSlugInput] = useState(initialSlug || "");
  const [isSavingSlug, setIsSavingSlug] = useState(false);

  const origin = typeof window !== "undefined" ? window.location.origin : "";
  const storeUrl = slug ? `${origin}/store/${slug}` : "";

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      const res = await generateAdminStoreSlug();
      if (res.success && res.slug) {
        setSlug(res.slug);
        setSlugInput(res.slug);
        toast.success("✅ Store created successfully!");
      } else {
        toast.error(res.error || "Failed to create store");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDelete = async () => {
    if (!confirm("Are you sure? This will remove your store link. Existing customers will no longer be able to access it.")) return;
    setIsDeleting(true);
    try {
      const res = await deleteAdminStore();
      if (res.success) {
        setSlug(null);
        setSlugInput("");
        toast.success("Store link removed");
      } else {
        toast.error(res.error || "Failed to remove store");
      }
    } finally {
      setIsDeleting(false);
    }
  };

  const handleSaveSlug = async () => {
    setIsSavingSlug(true);
    try {
      const res = await updateStoreSlug(slugInput);
      if (res.success && res.slug) {
        setSlug(res.slug);
        setSlugInput(res.slug);
        setIsEditingSlug(false);
        toast.success("Store URL updated!");
      } else {
        toast.error(res.error || "Failed to update URL");
      }
    } finally {
      setIsSavingSlug(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(storeUrl);
    setCopied(true);
    toast.success("Link copied!");
    setTimeout(() => setCopied(false), 2000);
  };

  const shareStore = async () => {
    if (navigator.share) {
      await navigator.share({ title: `${adminName}'s Data Store`, url: storeUrl });
    } else {
      copyToClipboard();
    }
  };

  // No store yet
  if (!slug) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-6 animate-in">
        <div className="text-center space-y-4">
          <div className="inline-flex p-6 bg-primary/10 rounded-full">
            <Store className="h-16 w-16 text-primary" />
          </div>
          <h2 className="text-3xl font-black font-outfit">Create Your Store</h2>
          <p className="text-muted-foreground max-w-md">
            Get a shareable link where customers can buy data directly from you — no account needed on their end.
          </p>
        </div>
        <button
          disabled={isGenerating}
          onClick={handleGenerate}
          className="px-8 py-4 bg-primary text-primary-foreground rounded-2xl font-bold text-lg flex items-center space-x-3 hover:brightness-110 transition-all disabled:opacity-70 shadow-lg shadow-primary/20"
        >
          {isGenerating ? <Loader2 className="h-5 w-5 animate-spin" /> : <Store className="h-5 w-5" />}
          <span>{isGenerating ? "Creating..." : "Create My Store"}</span>
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black font-outfit">My Store</h1>
          <p className="text-muted-foreground">Manage your shareable data store and its settings.</p>
        </div>
        <div className="flex items-center space-x-2">
          <a
            href={`/store/${slug}`}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center space-x-2 px-4 py-2 border rounded-xl font-bold text-sm hover:bg-muted transition-all"
          >
            <ExternalLink className="h-4 w-4" />
            <span>Preview Store</span>
          </a>
          <button
            onClick={shareStore}
            className="flex items-center space-x-2 px-4 py-2 bg-primary text-primary-foreground rounded-xl font-bold text-sm hover:brightness-110 transition-all"
          >
            <Share2 className="h-4 w-4" />
            <span>Share</span>
          </button>
        </div>
      </div>

      {/* Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        <div className="glass rounded-2xl p-5 border border-border/50">
          <p className="text-[10px] uppercase font-black tracking-widest text-muted-foreground mb-1">Total Bundles</p>
          <p className="text-3xl font-black font-outfit text-primary">{bundles.length}</p>
        </div>
        <div className="glass rounded-2xl p-5 border border-border/50">
          <p className="text-[10px] uppercase font-black tracking-widest text-muted-foreground mb-1">Store Orders</p>
          <p className="text-3xl font-black font-outfit">{storeOrderCount}</p>
        </div>
        <div className="glass rounded-2xl p-5 border border-border/50 col-span-2 md:col-span-1">
          <p className="text-[10px] uppercase font-black tracking-widest text-muted-foreground mb-1">Status</p>
          <span className="inline-flex items-center space-x-2 bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-black">
            <span className="h-2 w-2 rounded-full bg-green-500 animate-pulse inline-block" />
            <span>LIVE</span>
          </span>
        </div>
      </div>

      {/* Store URL Card */}
      <div className="glass rounded-2xl p-6 border border-border/50 shadow-sm space-y-5">
        <div className="flex items-center justify-between">
          <h3 className="font-bold flex items-center space-x-2">
            <Store className="h-5 w-5 text-primary" />
            <span>Store Link</span>
          </h3>
          <div className="flex items-center space-x-2">
            {!isEditingSlug && (
              <button
                onClick={() => setIsEditingSlug(true)}
                className="flex items-center space-x-1 px-3 py-1.5 text-xs font-bold border rounded-lg hover:bg-muted transition-all"
              >
                <Edit3 className="h-3 w-3" />
                <span>Edit URL</span>
              </button>
            )}
            <button
              onClick={handleDelete}
              disabled={isDeleting}
              className="flex items-center space-x-1 px-3 py-1.5 text-xs font-bold text-red-600 border border-red-200 rounded-lg hover:bg-red-50 transition-all"
            >
              {isDeleting ? <Loader2 className="h-3 w-3 animate-spin" /> : <Trash2 className="h-3 w-3" />}
              <span>Remove</span>
            </button>
          </div>
        </div>

        {isEditingSlug ? (
          <div className="space-y-3">
            <p className="text-xs text-muted-foreground">Customize your store URL slug (only lowercase letters, numbers and dashes):</p>
            <div className="flex items-center space-x-2">
              <span className="text-sm text-muted-foreground whitespace-nowrap font-mono">{origin}/store/</span>
              <input
                type="text"
                value={slugInput}
                onChange={(e) => setSlugInput(e.target.value)}
                className="flex-1 border border-primary rounded-lg px-3 py-2 text-sm font-mono outline-none focus:ring-2 focus:ring-primary/20"
                placeholder="my-store-name"
              />
              <button
                onClick={handleSaveSlug}
                disabled={isSavingSlug}
                className="px-4 py-2 bg-primary text-primary-foreground rounded-lg text-sm font-bold disabled:opacity-70 flex items-center space-x-1"
              >
                {isSavingSlug ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                <span>Save</span>
              </button>
              <button
                onClick={() => { setIsEditingSlug(false); setSlugInput(slug); }}
                className="p-2 rounded-lg border hover:bg-muted transition-all"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          </div>
        ) : (
          <div className="flex items-center space-x-2 bg-muted/30 p-3 rounded-xl border border-border">
            <code className="text-sm font-mono truncate flex-1 text-primary">{storeUrl}</code>
            <button
              onClick={copyToClipboard}
              className="p-2 hover:bg-background rounded-lg transition-all active:scale-95 text-primary flex-shrink-0"
            >
              {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
            </button>
          </div>
        )}

        <p className="text-[11px] text-muted-foreground">
          Share this link with customers. They can browse and buy bundles without creating an account.
        </p>
      </div>

      {/* Bundles Preview */}
      <div className="glass rounded-2xl p-6 border border-border/50 shadow-sm space-y-5">
        <div className="flex items-center justify-between">
          <h3 className="font-bold flex items-center space-x-2">
            <ShoppingBag className="h-5 w-5 text-primary" />
            <span>Store Bundles</span>
          </h3>
          <a
            href="/admin/pricing"
            className="text-xs font-bold text-primary hover:underline flex items-center space-x-1"
          >
            <Edit3 className="h-3 w-3" />
            <span>Edit Prices</span>
          </a>
        </div>
        <p className="text-xs text-muted-foreground -mt-2">
          Your store displays all active bundles. Manage pricing and availability from the <strong>Pricing</strong> tab.
        </p>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-muted/50 border-b">
              <tr>
                <th className="px-4 py-3 text-left font-bold text-[11px] uppercase tracking-wider">Network</th>
                <th className="px-4 py-3 text-left font-bold text-[11px] uppercase tracking-wider">Size</th>
                <th className="px-4 py-3 text-left font-bold text-[11px] uppercase tracking-wider">Customer Price</th>
                <th className="px-4 py-3 text-left font-bold text-[11px] uppercase tracking-wider">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {bundles.slice(0, 10).map((bundle: any) => (
                <tr key={bundle.id} className="hover:bg-muted/20 transition-colors">
                  <td className="px-4 py-3 font-bold text-primary">{bundle.network}</td>
                  <td className="px-4 py-3">{bundle.size}</td>
                  <td className="px-4 py-3 font-bold">GHS {Number(bundle.userPrice).toFixed(2)}</td>
                  <td className="px-4 py-3">
                    <span className={cn(
                      "px-2 py-0.5 rounded-full text-[10px] font-black uppercase",
                      bundle.isActive ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
                    )}>
                      {bundle.isActive ? "Active" : "Hidden"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {bundles.length > 10 && (
            <p className="text-center text-xs text-muted-foreground mt-3">
              + {bundles.length - 10} more bundles. <a href="/admin/pricing" className="text-primary font-bold hover:underline">Manage all →</a>
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

import prisma from "@/lib/prisma";
export const dynamic = "force-dynamic";

import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { redirect } from "next/navigation";
import StoreManager from "./StoreManager";

export default async function AdminStorePage() {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") redirect("/");

  const admin = await prisma.user.findUnique({
    where: { id: (session.user as any).id },
    select: { id: true, name: true, storeSlug: true }
  });

  const bundles = await prisma.bundle.findMany({
    orderBy: [{ network: "asc" }, { userPrice: "asc" }]
  });

  const storeOrderCount = admin?.storeSlug
    ? await prisma.order.count({ where: { agentId: admin.id } })
    : 0;

  return (
    <StoreManager
      initialSlug={admin?.storeSlug || null}
      adminName={admin?.name || "Admin"}
      bundles={JSON.parse(JSON.stringify(bundles))}
      storeOrderCount={storeOrderCount}
    />
  );
}

"use client";

import { useState } from "react";
import { X, Store, Mail, Phone, Lock, Loader2 } from "lucide-react";
import { createStore } from "./actions";
import { toast } from "react-hot-toast";

interface CreateStoreModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function CreateStoreModal({ isOpen, onClose }: CreateStoreModalProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    password: "",
  });

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const res = await createStore(formData);
      if (res.success) {
        toast.success("Store created successfully");
        onClose();
        setFormData({ name: "", email: "", phone: "", password: "" });
      } else {
        toast.error(res.error || "Failed to create store");
      }
    } catch (error) {
      toast.error("Something went wrong");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-background w-full max-w-md rounded-2xl shadow-2xl border border-border overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-border flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="p-2 bg-primary/10 rounded-lg">
              <Store className="h-5 w-5 text-primary" />
            </div>
            <h2 className="text-xl font-bold font-outfit">Create New Store</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-muted rounded-full transition-colors">
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Store/Owner Name</label>
            <div className="relative">
              <Store className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                required
                type="text"
                placeholder="e.g. Kojo's Data Hub"
                className="w-full pl-10 pr-4 py-3 rounded-xl bg-muted/30 border border-border focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Email Address</label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                required
                type="email"
                placeholder="kojo@example.com"
                className="w-full pl-10 pr-4 py-3 rounded-xl bg-muted/30 border border-border focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Phone Number</label>
            <div className="relative">
              <Phone className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                required
                type="tel"
                placeholder="024XXXXXXX"
                className="w-full pl-10 pr-4 py-3 rounded-xl bg-muted/30 border border-border focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Initial Password</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                required
                type="text"
                placeholder="Minimum 8 characters"
                className="w-full pl-10 pr-4 py-3 rounded-xl bg-muted/30 border border-border focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          </div>

          <div className="pt-4">
            <button
              disabled={isSubmitting}
              type="submit"
              className="w-full py-4 bg-primary text-primary-foreground font-bold rounded-xl shadow-lg shadow-primary/20 hover:brightness-110 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 disabled:opacity-70"
            >
              {isSubmitting ? (
                <Loader2 className="h-5 w-5 animate-spin" />
              ) : (
                <>
                  <Store className="h-5 w-5" />
                  <span>Create Store Account</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { formatCurrency, cn } from "@/lib/utils";
import { UserCog, Trash2, X, Shield, User, Star, Store, Plus, Search } from "lucide-react";
import { toast } from "react-hot-toast";
import { deleteUser, updateUserRole } from "./actions";
import CreateStoreModal from "./CreateStoreModal";

interface UserType {
  id: string;
  name: string;
  email: string;
  role: string;
  balance: any;
  createdAt: any;
  _count: {
    orders: number;
  };
  todayOrderCount: number;
}

export default function UserManagementClient({ users: initialUsers }: { users: UserType[] }) {
  const [users, setUsers] = useState(initialUsers);
  const [isProcessing, setIsProcessing] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState("most_orders_today");

  const filteredUsers = users
    .filter(u =>
      (u.name || "").toLowerCase().includes(search.toLowerCase()) ||
      (u.email || "").toLowerCase().includes(search.toLowerCase())
    )
    .sort((a, b) => {
      switch (sortBy) {
        case "newest":
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        case "oldest":
          return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        case "total_orders":
          return b._count.orders - a._count.orders;
        case "balance":
          return Number(b.balance) - Number(a.balance);
        case "most_orders_today":
        default:
          if (b.todayOrderCount !== a.todayOrderCount) {
            return b.todayOrderCount - a.todayOrderCount;
          }
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      }
    });

  const handleDelete = async (userId: string, name: string) => {
    if (!confirm(`Are you sure you want to delete user ${name}? This action cannot be undone.`)) return;

    setIsProcessing(userId);
    const res = await deleteUser(userId);
    if (res.success) {
      toast.success("User deleted successfully");
      setUsers(users.filter(u => u.id !== userId));
    } else {
      toast.error(res.error || "Failed to delete user");
    }
    setIsProcessing(null);
  };

  const handleRoleChange = async (userId: string, currentRole: string) => {
    const roles = ["USER", "AGENT", "ADMIN"];
    const nextRole = roles[(roles.indexOf(currentRole) + 1) % roles.length];
    
    if (!confirm(`Change role from ${currentRole} to ${nextRole}?`)) return;

    setIsProcessing(userId);
    const res = await updateUserRole(userId, nextRole);
    if (res.success) {
      toast.success(`Role updated to ${nextRole}`);
      setUsers(users.map(u => u.id === userId ? { ...u, role: nextRole } : u));
    } else {
      toast.error(res.error || "Failed to update role");
    }
    setIsProcessing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 px-2">
        <h2 className="text-xl font-bold font-outfit">Platform Users</h2>
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <input
              type="text"
              placeholder="Search by name or email..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="pl-9 pr-4 py-2.5 rounded-xl border border-border bg-background text-sm font-medium focus:outline-none focus:ring-2 focus:ring-primary/30 w-64"
            />
            {search && (
              <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="px-4 py-2.5 rounded-xl border border-border bg-background text-sm font-medium focus:outline-none focus:ring-2 focus:ring-primary/30 text-muted-foreground cursor-pointer"
          >
            <option value="most_orders_today">Most Orders Today</option>
            <option value="newest">Newest Joined First</option>
            <option value="oldest">Oldest Joined First</option>
            <option value="total_orders">Highest Total Orders</option>
            <option value="balance">Highest Wallet Balance</option>
          </select>

          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center space-x-2 px-6 py-2.5 bg-primary text-primary-foreground rounded-xl font-bold hover:brightness-110 transition-all shadow-lg shadow-primary/20 active:scale-95"
          >
            <Store className="h-4 w-4" />
            <span>Create Store</span>
          </button>
        </div>
      </div>

      <CreateStoreModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />

      <div className="glass rounded-2xl overflow-hidden border border-border/50 shadow-sm">
        <div className="overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="bg-muted/50 border-b">
            <tr>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider">User Details</th>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider text-center">Role</th>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider text-center">Orders</th>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider">Balance</th>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider">Joined</th>
              <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {filteredUsers.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-16 text-center text-muted-foreground text-sm">
                  No users found matching &ldquo;{search}&rdquo;
                </td>
              </tr>
            )}
            {filteredUsers.map((user, index) => (
              <tr key={user.id} className={cn("hover:bg-muted/30 transition-colors", isProcessing === user.id && "opacity-50 pointer-events-none")}>
                <td className="px-6 py-4">
                    <div className="flex flex-col">
                        <span className="font-bold text-base">{user.name || "No Name"}</span>
                        <span className="text-sm text-muted-foreground">{user.email || "No Email"}</span>
                    </div>
                </td>
                <td className="px-6 py-4 text-center">
                  <span className={cn(
                    "inline-flex items-center space-x-1 px-3 py-1 rounded-full text-xs font-black uppercase tracking-widest",
                    user.role === "ADMIN" ? "bg-red-100 text-red-600" :
                    user.role === "AGENT" ? "bg-indigo-100 text-indigo-600" : "bg-slate-100 text-slate-600"
                  )}>
                    {user.role === "ADMIN" ? <Shield className="h-3 w-3" /> : 
                     user.role === "AGENT" ? <Star className="h-3 w-3" /> : <User className="h-3 w-3" />}
                    <span>{user.role}</span>
                  </span>
                </td>
                <td className="px-6 py-4 text-center">
                  <div className="flex flex-col items-center">
                    <span className={cn(
                        "inline-flex items-center justify-center h-8 w-8 rounded-full font-black text-xs transition-all",
                        user.todayOrderCount > 0 ? "bg-green-100 text-green-700 scale-110 shadow-sm" : "bg-muted text-muted-foreground opacity-50"
                    )}>
                      {user.todayOrderCount}
                    </span>
                    <span className="text-[10px] text-muted-foreground mt-1 font-bold uppercase tracking-tighter">
                        {user._count.orders} Total
                    </span>
                    {user.todayOrderCount > 0 && index === 0 && (
                        <span className="text-[8px] bg-yellow-400 text-black px-1 rounded-sm font-black mt-1 animate-pulse">TOP</span>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4 font-mono font-bold text-primary">
                    {formatCurrency(user.balance.toString())}
                </td>
                <td className="px-6 py-4 text-muted-foreground text-sm">
                  {new Date(user.createdAt).toLocaleDateString()} <br />
                  <span className="text-xs opacity-75">{new Date(user.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </td>
                <td className="px-6 py-4 text-right space-x-1">
                  <button 
                    onClick={() => handleRoleChange(user.id, user.role)}
                    title="Cycle Role" 
                    className="p-2 hover:bg-primary/5 text-primary rounded-xl transition-all active:scale-90"
                  >
                      <UserCog className="h-5 w-5" />
                  </button>
                  <button 
                    onClick={() => handleDelete(user.id, user.name || "User")}
                    title="Delete User" 
                    className="p-2 hover:bg-red-50 text-red-500 rounded-xl transition-all active:scale-90"
                  >
                      <Trash2 className="h-5 w-5" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  </div>
  );
}

"use server";

import prisma from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import bcrypt from "bcryptjs";
import crypto from "crypto";
import { getSupplierForBundle, placeOrderOnSupplier } from "@/lib/supplierBridge";
import { normalizeOrderStatus } from "@/lib/utils";
import { processOrderCommission } from "@/lib/commissions";

async function ensureAdmin() {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") {
    throw new Error("Unauthorized");
  }
}

export async function updateUserRole(userId: string, newRole: string) {
  try {
    await ensureAdmin();
    
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new Error("User not found");

    const data: any = { role: newRole };

    // If becoming an agent and has no slug, generate one with collision check
    if (newRole === "AGENT" && !user.storeSlug) {
      const baseName = (user.name || "agent").toLowerCase().replace(/[^a-z0-9]/g, "-").replace(/-+/g, "-");
      let slug = "";
      for (let i = 0; i < 5; i++) {
        const candidate = `${baseName}-${Math.floor(10000 + Math.random() * 90000)}`;
        const taken = await prisma.user.findUnique({ where: { storeSlug: candidate } });
        if (!taken) { slug = candidate; break; }
      }
      data.storeSlug = slug || `${baseName}-${Date.now()}`;
      
      // Also set a default expiry if not set
      if (!user.agentExpiry) {
        const expiry = new Date();
        expiry.setDate(expiry.getDate() + 30);
        data.agentExpiry = expiry;
      }
    }

    await prisma.user.update({
      where: { id: userId },
      data
    });

    revalidatePath("/admin/users");
    revalidatePath("/admin/wallet");
    return { success: true };
  } catch (error: any) {
    return { success: false, error: error.message || "Failed to update role" };
  }
}

export async function deleteUser(userId: string) {
  try {
    await ensureAdmin();

    // Check if user has orders - we might want to delete orders or prevent deletion
    // For now, let's just delete the user (Prisma will fail if there are FK constraints unless set to cascade)
    // In schema.prisma, Order has fields [userId] references [id]. Default is restrict.
    
    // Better: just delete the user and let the DB handle it if cascading is on, 
    // or manually delete/disconnect if needed.
    // Let's assume we want to keep orders but remove the user? No, usually delete everything.
    
    await prisma.user.delete({
      where: { id: userId }
    });

    revalidatePath("/admin/users");
    revalidatePath("/admin/wallet");
    return { success: true };
  } catch (error: any) {
    console.error("Delete user error:", error);
    return { success: false, error: "Failed to delete user. They might have existing orders." };
  }
}

export async function updateUserBalance(userId: string, amount: number) {
  try {
    await ensureAdmin();

    const type = amount >= 0 ? "CREDIT" : "DEBIT";
    const ref = `ADMIN-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

    await prisma.$transaction([
      prisma.user.update({
        where: { id: userId },
        data: { balance: { increment: amount } }
      }),
      prisma.walletTransaction.create({
        data: {
          userId,
          amount: Math.abs(amount),
          type,
          reference: ref,
          description: `Admin manual ${type.toLowerCase()}`
        }
      })
    ]);

    revalidatePath("/admin/users");
    revalidatePath("/admin/wallet");
    revalidatePath("/dashboard");
    return { success: true };
  } catch (error: any) {
    console.error("Update balance error:", error);
    return { success: false, error: "Failed to update balance" };
  }
}


export async function createStore(data: { name: string, email: string, phone: string, password?: string }) {
  try {
    await ensureAdmin();

    const existingUser = await prisma.user.findUnique({
      where: { email: data.email.toLowerCase() }
    });

    if (existingUser) {
      return { success: false, error: "Email already exists" };
    }

    // MED-3: Never default to a weak password — require one or generate a secure random one
    const rawPassword = data.password && data.password.length >= 8
      ? data.password
      : crypto.randomBytes(10).toString("hex"); // 20-char random if not supplied

    const hashedPassword = await bcrypt.hash(rawPassword, 12);

    // LOW-4: Generate unique slug with collision check
    const baseName = data.name.toLowerCase().replace(/[^a-z0-9]/g, "-").replace(/-+/g, "-");
    let storeSlug = "";
    for (let i = 0; i < 5; i++) {
      const candidate = `${baseName}-${Math.floor(10000 + Math.random() * 90000)}`;
      const taken = await prisma.user.findUnique({ where: { storeSlug: candidate } });
      if (!taken) { storeSlug = candidate; break; }
    }
    if (!storeSlug) storeSlug = `${baseName}-${Date.now()}`;

    // Default expiry: 30 days for admin-created stores
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 30);

    await prisma.user.create({
      data: {
        name: data.name,
        email: data.email.toLowerCase(),
        phone: data.phone,
        password: hashedPassword,
        role: "AGENT",
        storeSlug: storeSlug,
        agentExpiry: expiry,
      }
    });

    revalidatePath("/admin/users");
    // Return the raw password so admin can communicate it to the agent
    return { success: true, generatedPassword: !data.password ? rawPassword : undefined };
  } catch (error: any) {
    console.error("Create store error:", error);
    return { success: false, error: error.message || "Failed to create store" };
  }
}

