export async function getFailedTopups() {
  try {
    await ensureAdmin();
    const items = await prisma.failedTopup.findMany({
      where: { status: "PENDING" },
      orderBy: { createdAt: "desc" }
    });
    return { success: true, data: items };
  } catch (error: any) {
    return { success: false, error: error.message || "Failed to fetch" };
  }
}

export async function approveFailedTopup(id: string) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || (session.user as any).role !== "ADMIN") {
      return { success: false, error: "Unauthorized" };
    }
    const adminId = (session.user as any).id;

    const record = await prisma.failedTopup.findUnique({ where: { id } });
    if (!record) return { success: false, error: "Record not found" };
    if (record.status !== "PENDING") return { success: false, error: "Already resolved" };

    // Find the user — prefer the stored userId, fall back to email lookup
    const user = record.userId
      ? await prisma.user.findUnique({ where: { id: record.userId } })
      : await prisma.user.findUnique({ where: { email: record.email } });

    if (!user) return { success: false, error: "No matching user account found. Resolve manually." };

    const ref = `TOPUP-MANUAL-${record.reference}`;
    const amount = Number(record.amount);

    // Check if this reference was already credited (idempotency guard)
    const alreadyCredited = await prisma.walletTransaction.findFirst({
      where: { reference: ref }
    });
    if (alreadyCredited) {
      // Mark resolved and bail out
      await prisma.failedTopup.update({
        where: { id },
        data: { status: "APPROVED", resolvedAt: new Date(), resolvedBy: adminId }
      });
      revalidatePath("/admin/wallet");
      return { success: true };
    }

    await prisma.$transaction([
      prisma.user.update({
        where: { id: user.id },
        data: { balance: { increment: amount } }
      }),
      prisma.walletTransaction.create({
        data: {
          userId: user.id,
          amount,
          type: "TOPUP",
          reference: ref,
          description: `Manual top-up approval by admin (ref: ${record.reference})`
        }
      }),
      prisma.failedTopup.update({
        where: { id },
        data: { status: "APPROVED", resolvedAt: new Date(), resolvedBy: adminId, userId: user.id }
      })
    ]);

    revalidatePath("/admin/wallet");
    revalidatePath("/dashboard");
    return { success: true };
  } catch (error: any) {
    console.error("Approve failed topup error:", error);
    return { success: false, error: error.message || "Failed to approve top-up" };
  }
}

export async function rejectFailedTopup(id: string) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || (session.user as any).role !== "ADMIN") {
      return { success: false, error: "Unauthorized" };
    }
    const adminId = (session.user as any).id;

    const record = await prisma.failedTopup.findUnique({ where: { id } });
    if (!record) return { success: false, error: "Record not found" };
    if (record.status !== "PENDING") return { success: false, error: "Already resolved" };

    await prisma.failedTopup.update({
      where: { id },
      data: { status: "REJECTED", resolvedAt: new Date(), resolvedBy: adminId }
    });

    revalidatePath("/admin/wallet");
    return { success: true };
  } catch (error: any) {
    console.error("Reject failed topup error:", error);
    return { success: false, error: error.message || "Failed to reject top-up" };
  }
}

export async function retryOrder(orderId: string, debitOption: "CUSTOMER" | "ADMIN" | "NONE") {
  try {
    const session = await getServerSession(authOptions);
    if (!session || (session.user as any).role !== "ADMIN") {
      return { success: false, error: "Unauthorized" };
    }
    const adminId = (session.user as any).id;

    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { bundle: true }
    });

    if (!order) return { success: false, error: "Order not found" };
    if (order.status !== "FAILED") {
      return { success: false, error: "Only failed orders can be retried" };
    }

    const orderAmount = Number(order.amount);

    if (debitOption === "ADMIN") {
      const admin = await prisma.user.findUnique({
        where: { id: adminId },
        select: { balance: true }
      });
      const adminBal = Number(admin?.balance ?? 0);
      if (!admin || adminBal < orderAmount) {
        return {
          success: false,
          error: `Insufficient admin wallet balance. You need GHS ${orderAmount.toFixed(2)} but have GHS ${adminBal.toFixed(2)} to replace this order.`
        };
      }
    } else if (debitOption === "CUSTOMER") {
      if (!order.userId) {
        return { success: false, error: "Cannot debit customer for guest checkout order" };
      }
      const customer = await prisma.user.findUnique({
        where: { id: order.userId },
        select: { balance: true }
      });
      const customerBal = Number(customer?.balance ?? 0);
      if (!customer || customerBal < orderAmount) {
        return {
          success: false,
          error: `Insufficient customer wallet balance. Customer needs GHS ${orderAmount.toFixed(2)} but has GHS ${customerBal.toFixed(2)}.`
        };
      }
    }

    // Run order status update and wallet deduction in a transaction
    await prisma.$transaction(async (tx) => {
      await tx.order.update({
        where: { id: orderId },
        data: {
          status: "PROCESSING",
          failureReason: null,
          supplierStatus: "RETRYING"
        }
      });

      if (debitOption === "ADMIN") {
        await tx.user.update({
          where: { id: adminId },
          data: { balance: { decrement: order.amount } }
        });

        await tx.walletTransaction.create({
          data: {
            userId: adminId,
            amount: order.amount,
            type: "DEBIT",
            reference: `RETRY-DEBIT-${order.id}`,
            description: `Replace/retry failed order #${order.id.substring(0, 8)} (Admin funded)`
          }
        });
      } else if (debitOption === "CUSTOMER" && order.userId) {
        await tx.user.update({
          where: { id: order.userId },
          data: { balance: { decrement: order.amount } }
        });

        await tx.walletTransaction.create({
          data: {
            userId: order.userId,
            amount: order.amount,
            type: "DEBIT",
            reference: `RETRY-DEBIT-${order.id}`,
            description: `Re-debit for replaced order #${order.id.substring(0, 8)} after retry`
          }
        });
      }
    });

    const { supplierProductId: resolvedProductId, supplierType } = await getSupplierForBundle(order.bundleId);
    const effectiveProductId = resolvedProductId || order.bundle.supplierProductId;

    if (!effectiveProductId) {
      await prisma.order.update({
        where: { id: orderId },
        data: {
          status: "FAILED",
          failureReason: "No supplier product ID configured for retry"
        }
      });
      return { success: false, error: "Bundle missing supplier product ID configuration" };
    }

    const supplierRes = await placeOrderOnSupplier({
      bundleId: order.bundleId,
      supplierProductId: effectiveProductId,
      phone: order.phone,
      reference: order.id
    });

    if (supplierRes.success) {
      const res = supplierRes as any;
      const supplierOrderId = res.supplierOrderId || res.supplier_order_id;
      const rawStatus = res.status || "PROCESSING";
      const normalizedStatus = normalizeOrderStatus(rawStatus);

      await prisma.order.update({
        where: { id: orderId },
        data: {
          status: normalizedStatus,
          supplierStatus: rawStatus,
          supplierOrderId: supplierOrderId,
          supplierType: supplierType
        }
      });

      if (normalizedStatus === "COMPLETED") {
        await processOrderCommission(orderId);
      }

      revalidatePath("/admin/orders");
      revalidatePath(`/admin/orders/${orderId}`);
      revalidatePath("/dashboard/orders");
      return { success: true, message: `Order replaced successfully! Supplier ID: ${supplierOrderId}` };
    } else {
      await prisma.order.update({
        where: { id: orderId },
        data: {
          status: "FAILED",
          failureReason: supplierRes.error || "Retry failed at supplier"
        }
      });
      return { success: false, error: supplierRes.error || "Supplier rejected the retry request" };
    }
  } catch (error: any) {
    console.error("Retry order error:", error);
    return { success: false, error: error.message || "Failed to retry order" };
  }
}

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { redirect } from "next/navigation";
import UserManagementClient from "./UserManagementClient";

export const dynamic = "force-dynamic";

export default async function AdminUsersPage() {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any).role !== "ADMIN") redirect("/");

  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);

  const rawUsers = await prisma.user.findMany({
    orderBy: { createdAt: "desc" },
    include: {
      _count: {
        select: { orders: true }
      },
      orders: {
        where: {
          createdAt: { gte: startOfToday },
          status: "COMPLETED"
        },
        select: { id: true }
      }
    },
    take: 500,
  });

  const users = rawUsers.map(u => ({
    ...u,
    todayOrderCount: u.orders.length
  })).sort((a, b) => {
    // Sort by today's orders first, then by join date (newest first)
    if (b.todayOrderCount !== a.todayOrderCount) {
      return b.todayOrderCount - a.todayOrderCount;
    }
    return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
  });

  return (
    <div className="space-y-8 animate-in">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-bold font-outfit">User Management</h1>
          <p className="text-muted-foreground">Manage roles, balances and user accounts</p>
        </div>
      </div>

      <UserManagementClient users={JSON.parse(JSON.stringify(users))} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { formatCurrency, cn } from "@/lib/utils";
import {
  Search,
  Plus,
  Minus,
  Loader2,
  User,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Clock,
  ChevronDown,
  ChevronUp,
} from "lucide-react";
import { toast } from "react-hot-toast";
import { updateUserBalance, approveFailedTopup, rejectFailedTopup } from "../users/actions";

interface UserType {
  id: string;
  name: string;
  email: string;
  balance: any;
  role: string;
}

interface FailedTopupType {
  id: string;
  reference: string;
  amount: any;
  email: string;
  userId: string | null;
  reason: string | null;
  createdAt: string;
}

export default function WalletManagementClient({
  initialUsers,
  initialFailedTopups,
}: {
  initialUsers: UserType[];
  initialFailedTopups: FailedTopupType[];
}) {
  const [users, setUsers] = useState(initialUsers);
  const [failedTopups, setFailedTopups] = useState(initialFailedTopups);
  const [search, setSearch] = useState("");
  const [isProcessing, setIsProcessing] = useState<string | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<{
    id: string;
    name: string;
    type: "CREDIT" | "DEBIT";
  } | null>(null);
  const [amount, setAmount] = useState("");
  const [topupsExpanded, setTopupsExpanded] = useState(true);

  const filteredUsers = users.filter(
    (user) =>
      user.name?.toLowerCase().includes(search.toLowerCase()) ||
      user.email?.toLowerCase().includes(search.toLowerCase())
  );

  const openModal = (userId: string, name: string, type: "CREDIT" | "DEBIT") => {
    setSelectedUser({ id: userId, name, type });
    setAmount("");
    setModalOpen(true);
  };

  const handleAction = async () => {
    if (!selectedUser) return;

    let numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0)
      return toast.error("Invalid amount. Please enter a positive number.");

    if (selectedUser.type === "DEBIT") {
      numAmount = -numAmount;
    }

    setIsProcessing(selectedUser.id);
    const res = await updateUserBalance(selectedUser.id, numAmount);

    if (res.success) {
      toast.success(
        `${selectedUser.type === "CREDIT" ? "Credited" : "Debited"} successfully`
      );
      setUsers(
        users.map((u) =>
          u.id === selectedUser.id
            ? { ...u, balance: (parseFloat(u.balance) + numAmount).toString() }
            : u
        )
      );
      setModalOpen(false);
    } else {
      toast.error(res.error || "Failed to update balance");
    }
    setIsProcessing(null);
  };

  const handleApproveTopup = async (id: string) => {
    setIsProcessing(id);
    const res = await approveFailedTopup(id);
    if (res.success) {
      toast.success("Top-up approved & wallet credited ✅");
      setFailedTopups((prev) => prev.filter((t) => t.id !== id));
    } else {
      toast.error(res.error || "Failed to approve top-up");
    }
    setIsProcessing(null);
  };

  const handleRejectTopup = async (id: string) => {
    setIsProcessing(id);
    const res = await rejectFailedTopup(id);
    if (res.success) {
      toast.success("Top-up dismissed");
      setFailedTopups((prev) => prev.filter((t) => t.id !== id));
    } else {
      toast.error(res.error || "Failed to reject top-up");
    }
    setIsProcessing(null);
  };

  return (
    <div className="space-y-8">

      {/* ── Failed Top-ups Section ───────────────────────────── */}
      <div className="glass rounded-3xl border border-border/50 shadow-sm overflow-hidden">
        {/* Header */}
        <button
          onClick={() => setTopupsExpanded((v) => !v)}
          className="w-full flex items-center justify-between px-6 py-5 bg-amber-50/60 dark:bg-amber-950/20 border-b border-amber-200/50 dark:border-amber-800/30 hover:bg-amber-50 dark:hover:bg-amber-950/30 transition-colors"
        >
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-amber-100 dark:bg-amber-900/40">
              <AlertTriangle className="h-5 w-5 text-amber-600 dark:text-amber-400" />
            </div>
            <div className="text-left">
              <h2 className="text-base font-bold font-outfit text-amber-900 dark:text-amber-200">
                Pending Top-up Approvals
              </h2>
              <p className="text-xs text-amber-700/70 dark:text-amber-400/70">
                Top-ups paid but not auto-credited — review and approve manually
              </p>
            </div>
            {failedTopups.length > 0 && (
              <span className="ml-2 px-2.5 py-0.5 rounded-full text-xs font-black bg-amber-500 text-white animate-pulse">
                {failedTopups.length}
              </span>
            )}
          </div>
          {topupsExpanded ? (
            <ChevronUp className="h-4 w-4 text-amber-600" />
          ) : (
            <ChevronDown className="h-4 w-4 text-amber-600" />
          )}
        </button>

        {/* Table */}
        {topupsExpanded && (
          <div className="overflow-x-auto">
            {failedTopups.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-14 text-muted-foreground gap-3">
                <CheckCircle2 className="h-10 w-10 text-emerald-400 opacity-70" />
                <p className="text-sm font-medium">All clear — no pending top-ups</p>
              </div>
            ) : (
              <table className="w-full text-left text-sm">
                <thead className="bg-muted/40 border-b">
                  <tr>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider">
                      Customer
                    </th>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider">
                      Amount
                    </th>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider hidden md:table-cell">
                      Reference
                    </th>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider hidden lg:table-cell">
                      Reason
                    </th>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider hidden sm:table-cell">
                      Date
                    </th>
                    <th className="px-6 py-4 font-semibold text-xs uppercase tracking-wider text-right">
                      Action
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {failedTopups.map((topup) => (
                    <tr
                      key={topup.id}
                      className={cn(
                        "hover:bg-amber-50/30 dark:hover:bg-amber-950/10 transition-colors",
                        isProcessing === topup.id && "opacity-50 pointer-events-none"
                      )}
                    >
                      {/* Customer */}
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="h-9 w-9 rounded-full bg-amber-100 dark:bg-amber-900/40 flex items-center justify-center shrink-0">
                            <User className="h-4 w-4 text-amber-600" />
                          </div>
                          <div>
                            <p className="font-bold text-sm leading-tight truncate max-w-[160px]">
                              {topup.email}
                            </p>
                            {topup.userId && (
                              <p className="text-[10px] text-muted-foreground font-mono">
                                uid: {topup.userId.slice(0, 10)}…
                              </p>
                            )}
                          </div>
                        </div>
                      </td>
                      {/* Amount */}
                      <td className="px-6 py-4">
                        <span className="font-mono font-black text-lg text-emerald-600">
                          {formatCurrency(topup.amount.toString())}
                        </span>
                      </td>
                      {/* Reference */}
                      <td className="px-6 py-4 hidden md:table-cell">
                        <span className="font-mono text-xs bg-muted px-2 py-1 rounded-lg text-muted-foreground truncate max-w-[140px] block">
                          {topup.reference}
                        </span>
                      </td>
                      {/* Reason */}
                      <td className="px-6 py-4 hidden lg:table-cell">
                        <span className="text-xs text-rose-600 dark:text-rose-400 max-w-[200px] block truncate" title={topup.reason || ""}>
                          {topup.reason || "—"}
                        </span>
                      </td>
                      {/* Date */}
                      <td className="px-6 py-4 hidden sm:table-cell">
                        <div className="flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock className="h-3.5 w-3.5" />
                          <span>
                            {new Date(topup.createdAt).toLocaleDateString("en-GB", {
                              day: "numeric",
                              month: "short",
                              year: "numeric",
                            })}
                          </span>
                        </div>
                      </td>
                      {/* Actions */}
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          {isProcessing === topup.id ? (
                            <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                          ) : (
                            <>
                              <button
