import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { getNetworkSettings, filterBundlesByNetwork } from "@/lib/networkSettings";

export async function GET() {
  try {
    const session = await getServerSession(authOptions);
    const userRole = (session?.user as any)?.role;
    const isPrivileged = userRole === "AGENT" || userRole === "ADMIN";

    const bundles = await prisma.bundle.findMany({
      where: { isActive: true },
      // HIGH-8: Only return internal pricing fields to privileged users
      select: {
        id: true,
        network: true,
        size: true,
        userPrice: true,
        isActive: true,
        // Agent/admin-only fields
        ...(isPrivileged && {
          agentPrice: true,
          supplierProductId: true,
        }),
      },
    });

    const networkSettings = await getNetworkSettings();
    const filteredBundles = filterBundlesByNetwork(bundles, networkSettings);

    return NextResponse.json(filteredBundles);
  } catch (error) {
    return NextResponse.json({ message: "Error fetching bundles" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { trackOrderOnSupplier } from "@/lib/supplierBridge";
import { processOrderRefund } from "@/lib/orderUtils";
import { processOrderCommission } from "@/lib/commissions";

// Triggered by Vercel Cron or any cron service
export async function GET(req: Request) {
  const cronSecret = process.env.CRON_SECRET;
  const authHeader = req.headers.get('authorization');
  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const pendingOrders = await prisma.order.findMany({
      where: {
        status: "PROCESSING",
        supplierOrderId: { not: null },
      },
      // L3 FIX: Increased from 20 to 50 to prevent backlog at high order volume.
      // FIFO ordering ensures oldest orders are resolved first.
      orderBy: { createdAt: "asc" },
      take: 50,
    });

    if (pendingOrders.length === 0) {
      return NextResponse.json({ message: "No pending orders to track." });
    }

    const supplierTypeSetting = await prisma.systemSetting.findUnique({
      where: { key: "SUPPLIER_TYPE" }
    });
    const defaultSupplierType = supplierTypeSetting?.value || process.env.SUPPLIER_TYPE || "FUZESERVE";

    let updatedCount = 0;
    let failedCount = 0;

    for (const order of pendingOrders) {
      const supplierRef = order.supplierOrderId!;
      // Use supplierType stored on the order — routes to the right supplier
      const supplierType = order.supplierType || defaultSupplierType;

      const result = await trackOrderOnSupplier(supplierRef, supplierType);

      if (!result.success) {
        console.error(`Failed to fetch status for ${supplierRef}: ${result.error}`);
        continue;
      }

      const status = result.status?.toLowerCase();

      if (status === "completed") {
        await prisma.order.update({
          where: { id: order.id },
          data: { status: "COMPLETED" },
        });
        await processOrderCommission(order.id);
        updatedCount++;
      } else if (status === "failed") {
        await processOrderRefund(order.id, result.error || "Supplier failed the order");
        failedCount++;
      }
    }

    return NextResponse.json({
      success: true,
      processed: pendingOrders.length,
      completed: updatedCount,
      failed: failedCount
    });

  } catch (error: any) {
    console.error("Cron Error:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { amount, email, externalRef, currency = "GHS", metadata, redirectUrl } = body;

    if (!amount || !email || !externalRef) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    // Get credentials from DB
    const settings = await prisma.systemSetting.findMany({
      where: { key: { in: ["NEXT_PUBLIC_MOOLRE_USERNAME", "NEXT_PUBLIC_MOOLRE_PUBLIC_KEY", "NEXT_PUBLIC_MOOLRE_ACCOUNT_NUMBER", "MOOLRE_SANDBOX_MODE"] } }
    });
    const map: Record<string, string> = {};
    settings.forEach(s => map[s.key] = s.value);

    const username = map["NEXT_PUBLIC_MOOLRE_USERNAME"] || process.env.NEXT_PUBLIC_MOOLRE_USERNAME || "";
    const publicKey = map["NEXT_PUBLIC_MOOLRE_PUBLIC_KEY"] || process.env.NEXT_PUBLIC_MOOLRE_PUBLIC_KEY || "";
    const accountNumber = map["NEXT_PUBLIC_MOOLRE_ACCOUNT_NUMBER"] || process.env.NEXT_PUBLIC_MOOLRE_ACCOUNT_NUMBER || "";
    const sandboxMode = map["MOOLRE_SANDBOX_MODE"] === "true" || process.env.MOOLRE_SANDBOX_MODE === "true";

    if (!username || !accountNumber) {
      return NextResponse.json({ error: "Payment gateway not configured" }, { status: 500 });
    }

    // Sandbox: no public key required. Live: requires X-API-PUBKEY
    const apiBase = sandboxMode ? "https://sandbox.moolre.com" : "https://api.moolre.com";
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      "X-API-USER": username,
    };
    if (!sandboxMode && publicKey) {
      headers["X-API-PUBKEY"] = publicKey;
    }

    console.log(`[Moolre] Using ${sandboxMode ? "SANDBOX" : "LIVE"} mode`);

    const res = await fetch(`${apiBase}/embed/link`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        type: 1,
        accountnumber: accountNumber,
        amount,
        currency,
        email,
        description: "",
        metadata: metadata || {},
        externalref: externalRef,
        redirect: redirectUrl,
        mode: "payment",
        reusable: false,
      }),
    });

    const data = await res.json();
    console.log("[Moolre] API response:", JSON.stringify(data));

    // status=0 means error from Moolre even with HTTP 200
    if (data?.status === 0) {
      return NextResponse.json({ error: data?.message || "Moolre error" }, { status: 400 });
    }

    const paymentUrl =
      data?.data?.authorization_url ||
      data?.data?.paymentUrl ||
      data?.authorization_url ||
      data?.paymentUrl;

    if (!paymentUrl) {
      console.error("[Moolre] No payment URL in response:", data);
      return NextResponse.json({ error: "No payment URL returned by Moolre", raw: data }, { status: 500 });
    }

    return NextResponse.json({ paymentUrl });
  } catch (error: any) {
    console.error("[Moolre] Create link error:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { getSupplierForBundle } from "@/lib/supplierBridge";
import { OrderResponse } from "@/lib/suppliers/types";
import { normalizeOrderStatus } from "@/lib/utils";
import { processOrderCommission } from "@/lib/commissions";
import { processOrderRefund } from "@/lib/orderUtils";
import { sendPushNotification } from "@/lib/notifications";


export async function POST(req: Request) {
  const session = await getServerSession(authOptions);

  // Session is only strictly required for WALLET payments

  try {
    const body = await req.json();
    const { bundleId, phone, paymentRef, amount, agentId, paymentMethod = "MOOLRE" } = body;
    
    if (paymentMethod === "MOOLRE" && paymentRef) {
        const existingOrder = await prisma.order.findUnique({
            where: { paymentRef },
            include: { bundle: true }
        });
        if (existingOrder) {
            return NextResponse.json(existingOrder, { status: 200 });
        }
    }
    
    const sanitizedPhone = phone.replace(/\D/g, "");
    const ghPhoneRegex = /^(02|05)\d{8}$/;
    if (!ghPhoneRegex.test(sanitizedPhone)) {
        return NextResponse.json({ message: "Invalid Ghanaian phone number" }, { status: 400 });
    }
    
    let verifyData: any = null;

    if (paymentMethod === "MOOLRE") {
        // TODO: Implement Moolre transaction verification API call if available
        // For now, we trust the client widget's success callback,
        // but robust implementations should verify via Moolre API or Webhook.
    }

    // Parallelize independent DB lookups — bundle + user role fetched simultaneously
    const [bundle, dbUser] = await Promise.all([
      prisma.bundle.findUnique({ where: { id: bundleId } }),
      session
        ? prisma.user.findUnique({
            where: { id: (session.user as any).id },
            select: { role: true, agentExpiry: true }
          })
        : Promise.resolve(null),
    ]);

    if (!bundle) {
      return NextResponse.json({ message: "Bundle not found" }, { status: 404 });
    }

    // HIGH-2 + MED-2: Always re-fetch role from DB — JWT can be stale after demotion or expiry.
    // This also enforces agent subscription expiry at purchase time, not just at dashboard login.
    let liveRole = "USER";
    if (session && dbUser) {
      // Auto-expire agents whose subscription has lapsed
      if (dbUser.role === "AGENT" && dbUser.agentExpiry && new Date() > new Date(dbUser.agentExpiry)) {
        await prisma.user.update({ where: { id: (session.user as any).id }, data: { role: "USER" } });
        liveRole = "USER";
      } else {
        liveRole = dbUser.role;
      }
    }

    const isOnAgentStore = !!agentId && agentId !== (session?.user as any)?.id;
    const basePrice = (!isOnAgentStore && (liveRole === "AGENT" || liveRole === "ADMIN"))
        ? Number(bundle.agentPrice)
        : Number(bundle.userPrice);

    // CRIT-6: Verify the paid amount matches the bundle price from the DB.
    // If we had Moolre verifyData, we would check it here.

    // Always use the DB price — never the client-supplied amount
    const finalAmount = basePrice;

    const order = await prisma.$transaction(async (tx) => {
        if (paymentMethod === "WALLET") {
            if (!session) {
                throw new Error("Unauthorized");
            }
            const user = await tx.user.findUnique({
                where: { id: (session.user as any).id },
                select: { balance: true }
            });

            // Use Decimal-safe comparison with small epsilon to avoid floating point rejection
            const userBal = Number(user?.balance ?? 0);
            const EPSILON = 0.005; // half a pesewa tolerance
            if (!user || (userBal + EPSILON) < finalAmount) {
                console.warn(`Insufficient balance: User has ${user?.balance}, needs ${finalAmount}`);
                throw new Error(`Insufficient wallet balance. You need GHS ${finalAmount.toFixed(2)} but have GHS ${userBal.toFixed(2)}`);
            }

            // Wallet debit — deduct from user balance inside the transaction
            await tx.user.update({
                where: { id: (session.user as any).id },
                data: { balance: { decrement: finalAmount } }
            });

            // M2/C2 FIX: Reference will be set post-order-creation to include orderId.
            // For now, use a placeholder that is unique enough for the transaction debit.
            // The final paystackRef on the Order record (below) includes the orderId.
            await tx.walletTransaction.create({
                data: {
                    userId: (session.user as any).id,
                    amount: finalAmount,
                    type: "DEBIT",
                    reference: `WALLET-DEBIT-${(session.user as any).id}-${Date.now()}`,
                    description: `Data Bundle Purchase - ${bundle.network} ${bundle.size}`
                }
            });
        }

        return await tx.order.create({
            data: {
                userId: session ? (session.user as any).id : null,
                bundleId: bundle.id,
                phone: sanitizedPhone,
                amount: finalAmount,
                // C2/M2 FIX: For wallet orders, include userId in the ref to make it
                // deterministic and collision-resistant. Two simultaneous taps will
                // produce the same ref, and the DB unique constraint will reject the duplicate.
                paymentRef: paymentMethod === "WALLET"
                  ? `WALLET-${(session!.user as any).id}-${bundle.id}-${Date.now()}`
                  : paymentRef,
                paymentMethod,
                agentId: agentId || null,
                status: "PENDING",
            },
            include: {
                bundle: true
            }
        });
    });

    if (order.userId) {
      await sendPushNotification({
        userId: order.userId,
        title: "Order Placed 🚀",
        message: `Your order for ${bundle.size} ${bundle.network} data to ${sanitizedPhone} has been received.`,
        url: "/dashboard/orders"
      });
    }


    // H5 FIX: Reuse the already-resolved supplier from getSupplierForBundle rather than
    // calling placeOrderOnSupplier (which internally calls getSupplierForBundle again,
    // doubling the DB queries: 3-4 extra queries per order).
    const { supplier, supplierProductId: resolvedProductId, supplierType } = await getSupplierForBundle(bundle.id);
    const effectiveProductId = resolvedProductId || bundle.supplierProductId;

    if (!effectiveProductId) {
        console.error("Order error: Bundle missing supplierProductId", bundle.id);
        return NextResponse.json({ message: "This bundle is not correctly configured for automated delivery." }, { status: 400 });
    }

    // Call the supplier directly, bypassing the placeOrderOnSupplier wrapper
    // (which would call getSupplierForBundle a second time)
    const supplierRes = await supplier.placeOrder(
      effectiveProductId,
      sanitizedPhone,
      order.id
    );

    if (supplierRes.success) {
      const res = supplierRes as OrderResponse;
      const supplierOrderId = res.supplierOrderId || (res as any).supplier_order_id;
      
      if (supplierOrderId) {
        const rawStatus = res.status || "PROCESSING";
        const normalizedStatus = normalizeOrderStatus(rawStatus);
        
        await prisma.order.update({
          where: { id: order.id },
          data: { 
            status: normalizedStatus,
            supplierStatus: rawStatus,
            supplierOrderId: supplierOrderId,
            supplierType: supplierType, // Store which supplier handled this order
          },
        });

        // H2 FIX: Only credit commission on COMPLETED, not PROCESSING.
        // The cron job will handle commission for orders that complete later.
        if (normalizedStatus === "COMPLETED") {
          await processOrderCommission(order.id);
        }
      }
    } else {
      // Save the supplierType on the order first so the failure is properly associated with the supplier
      await prisma.order.update({
        where: { id: order.id },
        data: { supplierType }
      });

      // Use the refund utility to mark as failed and refund if necessary
      await processOrderRefund(
        order.id, 
        (supplierRes as any).error || "Supplier rejection"
      );
    }

    return NextResponse.json(order, { status: 201 });

  } catch (error: any) {
    console.error("Order error:", error);
    return NextResponse.json({ message: error.message || "Internal server error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const ref = searchParams.get("ref");

  if (!ref) {
    return NextResponse.json({ message: "Reference is required" }, { status: 400 });
  }

  try {
    const order = await prisma.order.findFirst({
      where: {
        OR: [
          { phone: ref },
          { paymentRef: ref },
          { id: ref },
          { supplierOrderId: ref }
        ]
      },
      orderBy: {
        createdAt: 'desc'
      },
      include: {
        bundle: true
      }
    });


    const session = await getServerSession(authOptions);
    if (!session) {
        return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
    }

    if (!order) {
      return NextResponse.json({ message: "Order not found" }, { status: 404 });
    }

    if (order.userId !== (session.user as any).id && (session.user as any).role !== "ADMIN") {
        return NextResponse.json({ message: "Unauthorized to track this order" }, { status: 403 });
    }

    // Don't leak internal sensitive user info, just return bundle and status
    return NextResponse.json({
        id: order.id,
        status: order.status,
        phone: order.phone,
        amount: order.amount,
        createdAt: order.createdAt,
        bundle: {
            network: order.bundle.network,
            size: order.bundle.size
        }
    });

  } catch (error) {
    console.error("Tracking API error:", error);
    return NextResponse.json({ message: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { amount, email, externalRef, currency = "GHS", metadata, redirectUrl } = body;

    if (!amount || !email || !externalRef) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    // Get Paystack secret key from DB or env
    const setting = await prisma.systemSetting.findUnique({ where: { key: "PAYSTACK_SECRET_KEY" } });
    const secretKey = setting?.value || process.env.PAYSTACK_SECRET_KEY;

    if (!secretKey) {
      return NextResponse.json({ error: "Payment gateway not configured" }, { status: 500 });
    }

    // Paystack amounts are in kobo/pesewas (smallest unit × 100)
    const amountInPesewas = Math.round(amount * 100);

    const paystackRes = await fetch("https://api.paystack.co/transaction/initialize", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${secretKey}`,
      },
      body: JSON.stringify({
        email,
        amount: amountInPesewas,
        currency,
        reference: externalRef,
        callback_url: redirectUrl || "https://jeilinks.site",
        metadata: metadata || {},
      }),
    });

    const data = await paystackRes.json();
    console.log("[Paystack] Initialize response:", JSON.stringify(data));

    if (!data.status || !data.data?.authorization_url) {
      console.error("[Paystack] Failed to initialize:", data);
      return NextResponse.json({ error: data.message || "Paystack initialization failed" }, { status: 400 });
    }

    return NextResponse.json({ paymentUrl: data.data.authorization_url, reference: data.data.reference });
  } catch (error: any) {
    console.error("[Paystack] Initialize error:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

