import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { processOrderCommission } from "@/lib/commissions";
import { processOrderRefund } from "@/lib/orderUtils";
import { sendPushNotification } from "@/lib/notifications";


export async function POST(req: Request) {
  const secret = req.headers.get("x-webhook-secret");
  
  if (secret !== process.env.SUPPLIER_WEBHOOK_SECRET) {
    return new Response("Unauthorized", { status: 401 });
  }

  try {
    const body = await req.json();
    // body: { reference: string, supplier_order_id: string, status: 'processing' | 'completed' | 'failed' }
    
    const { reference, status, supplier_order_id } = body;

    if (!reference || typeof reference !== "string") {
      return NextResponse.json({ message: "Invalid reference" }, { status: 400 });
    }

    const mappedStatus: any = {
        'processing': 'PROCESSING',
        'completed': 'COMPLETED',
        'failed': 'FAILED'
    };

    const newStatus = mappedStatus[status?.toLowerCase()] || 'PROCESSING';

    // Validate order exists before updating (HIGH-7: prevent blind mutation of arbitrary IDs)
    const existingOrder = await prisma.order.findUnique({ where: { id: reference } });
    if (!existingOrder) {
      return NextResponse.json({ message: "Order not found" }, { status: 404 });
    }

    if (newStatus === "FAILED") {
      // MED-5: Process refund on failure (was missing)
      await processOrderRefund(reference, "Supplier reported failure via webhook");

      if (existingOrder.userId) {
        await sendPushNotification({
          userId: existingOrder.userId,
          title: "Order Failed ❌",
          message: `Your order for ${existingOrder.phone} could not be delivered. A refund has been processed if applicable.`,
          url: "/dashboard/orders"
        });
      }
    } else {
      const order = await prisma.order.update({
        where: { id: reference },
        data: { 
          status: newStatus,
          supplierOrderId: supplier_order_id
        },
      });

      // H2 FIX: Only credit commission on COMPLETED, not PROCESSING.
      if (newStatus === "COMPLETED") {
          await processOrderCommission(order.id);
      }

      if (order.userId) {
        const bundle = await prisma.bundle.findUnique({ where: { id: order.bundleId } });
        await sendPushNotification({
          userId: order.userId,
          title: newStatus === "COMPLETED" ? "Order Completed! ✅" : "Order Processing ⏳",
          message: newStatus === "COMPLETED"
            ? `Your ${bundle?.size} ${bundle?.network} data to ${order.phone} has been delivered.`
            : `Your order to ${order.phone} is being processed.`,
          url: "/dashboard/orders"
        });
      }
    }

    console.log(`Order ${reference} updated to ${newStatus}`);

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Supplier webhook error:", error);
    return NextResponse.json({ message: "Error processing webhook" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

export async function POST(req: Request) {
  const session = await getServerSession(authOptions);

  if (!session) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  try {
    const { reference } = await req.json();

    // 1. Verify Paystack Payment
    // C3 FIX: Read from DB setting first (same as orders route), then env fallback.
    // This ensures Paystack key rotations via the Admin Settings UI take effect immediately.
    const paystackSetting = await prisma.systemSetting.findUnique({ where: { key: "PAYSTACK_SECRET_KEY" } });
    const paystackSecret = paystackSetting?.value || process.env.PAYSTACK_SECRET_KEY;

    if (!paystackSecret) {
      console.error("upgrade-agent: PAYSTACK_SECRET_KEY not configured");
      return NextResponse.json({ message: "Payment configuration error" }, { status: 500 });
    }

    const verifyRes = await fetch(`https://api.paystack.co/transaction/verify/${reference}`, {
      headers: {
        Authorization: `Bearer ${paystackSecret}`,
      },
    });

    const verifyData = await verifyRes.json();

    // HIGH-5: Verify amount against the real subscription price from settings
    const agentFeeSetting = await prisma.systemSetting.findUnique({ where: { key: "AGENT_UPGRADE_FEE" } });
    const expectedPesewas = agentFeeSetting ? Number(agentFeeSetting.value) * 100 : 1000; // fallback to GHS 10

    if (!verifyRes.ok || verifyData.data.status !== "success" || verifyData.data.amount < expectedPesewas) {
      return NextResponse.json({ message: "Payment verification failed" }, { status: 400 });
    }

    // 2. Check if reference already used
    const existingTx = await prisma.walletTransaction.findUnique({
      where: { reference: reference }
    });

    if (existingTx) {
      return NextResponse.json({ message: "Payment already processed" }, { status: 400 });
    }

    // 3. Update User Role
    const userId = (session.user as any).id;
    const existingUser = await prisma.user.findUnique({ where: { id: userId } });

    // Compute new expiry (stack on top of existing if not yet expired)
    let newExpiry = new Date();
    if (existingUser?.agentExpiry && new Date(existingUser.agentExpiry) > new Date()) {
      newExpiry = new Date(existingUser.agentExpiry);
    }
    newExpiry.setDate(newExpiry.getDate() + 14);

    if (existingUser?.role === "AGENT" && existingUser.storeSlug) {
        // MED-6: Extend expiry on renewal (was missing before)
        await prisma.$transaction([
          prisma.user.update({
            where: { id: userId },
            data: { agentExpiry: newExpiry }
          }),
          prisma.walletTransaction.create({
            data: {
                userId,
                amount: verifyData.data.amount / 100,
                type: "CREDIT",
                reference: reference,
                description: "Agent Subscription Renewal"
            }
          })
        ]);
        return NextResponse.json({ message: "Subscription renewed", expiresAt: newExpiry }, { status: 200 });
    }

    const userName = session.user?.name || "agent";
    // L2 FIX: 9000-range suffix significantly reduces slug collision probability.
    const storeSlug = userName.toLowerCase().replace(/[^a-z0-9]/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "") + "-" + Math.floor(1000 + Math.random() * 9000);

    const user = await prisma.$transaction(async (tx) => {
        const u = await tx.user.update({
            where: { id: userId },
            data: {
                role: "AGENT",
                storeSlug: storeSlug,
                agentExpiry: newExpiry,
            },
        });

        await tx.walletTransaction.create({
            data: {
                userId,
                amount: verifyData.data.amount / 100,
                type: "CREDIT",
                reference: reference,
                description: "Agent Upgrade Fee"
            }
        });

        return u;
    });

    return NextResponse.json({ message: "Success", user }, { status: 200 });
  } catch (error) {
    console.error("Upgrade error:", error);
    return NextResponse.json({ message: "Internal server error" }, { status: 500 });
  }
}

