"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function upgradeToAgent(paymentRef: string) {
  const session = await getServerSession(authOptions);

  if (!session) {
    return { success: false, error: "Unauthorized" };
  }

  try {
    const userId = (session.user as any).id;

    // Helper: fetch WhatsApp group URL from settings
    const getCommunityUrl = async () => {
      const communitySettings = await prisma.systemSetting.findMany({
        where: { key: { in: ["WHATSAPP_CHANNEL_URL"] } }
      });
      return communitySettings.find(s => s.key === "WHATSAPP_CHANNEL_URL")?.value || "";
    };

    // 1. Check if the webhook already processed this payment and upgraded the user
    // We poll briefly in case the webhook fired almost immediately
    let attempts = 0;
    let existingTx = null;

    while (attempts < 3) {
      existingTx = await prisma.walletTransaction.findUnique({
        where: { reference: paymentRef }
      });

      if (existingTx) break;

      await new Promise(resolve => setTimeout(resolve, 1500));
      attempts++;
    }

    if (existingTx) {
      // Webhook already ran — user should already be AGENT. Just return the group link.
      const whatsappGroupUrl = await getCommunityUrl();
      revalidatePath("/dashboard");
      revalidatePath("/");
      return { success: true, whatsappGroupUrl, alreadyProcessed: true };
    }

    // If webhook hasn't processed it yet, we just assume success on the client 
    // and let the webhook upgrade the user asynchronously
    const whatsappGroupUrl = await getCommunityUrl();
    return { success: true, whatsappGroupUrl };

    // Everything else was moved to the webhook or above polling logic

  } catch (error: any) {
    console.error("Upgrade error:", error);
    return { success: false, error: error.message || "An internal error occurred" };
  }
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { toast } from "react-hot-toast";
import { topUpWallet } from "./topup-action";

import PaystackButton from "@/components/PaystackButton";

export function TopUpButton({ email, userId }: { email: string; userId: string }) {
  const router = useRouter();
  const [isProcessing, setIsProcessing] = useState(false);
  const [amount, setAmount] = useState("10"); // Default 10 GHS
  const [showInput, setShowInput] = useState(false);

  const handleSuccess = async (reference: any) => {
    setIsProcessing(true);
    const result = await topUpWallet(reference.reference);
    if (result.success) {
      toast.success(`Wallet topped up by GHS ${result.amount}!`);
      setShowInput(false);
      // Force the dashboard to re-fetch server data so the balance updates immediately
      router.refresh();
    } else {
      toast.error(result.error || "Failed to top up wallet");
    }
    setIsProcessing(false);
  };


  if (!showInput) {
    return (
      <button 
        onClick={() => setShowInput(true)}
        className="mt-6 w-full py-2 bg-primary text-primary-foreground rounded-xl text-sm font-semibold hover:brightness-110 active:scale-95 transition-all"
      >
        Top Up Wallet
      </button>
    );
  }

  return (
    <div className="mt-6 space-y-3 animate-in fade-in zoom-in duration-200">
      <div className="flex items-center space-x-2">
          <span className="text-xs font-bold text-muted-foreground uppercase">Amount (GHS)</span>
          <button onClick={() => setShowInput(false)} className="text-[10px] underline ml-auto">Cancel</button>
      </div>
      <input 
        type="number" 
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        className="w-full bg-background border rounded-lg px-3 py-2 text-sm focus:ring-1 focus:ring-primary outline-none"
        placeholder="Enter amount"
      />
      <PaystackButton
        email={email}
        amount={parseFloat(amount)}
        label={isProcessing ? "Processing..." : `Pay GHS ${amount}`}
        className="w-full py-2 bg-green-600 text-white rounded-xl text-sm font-bold hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
        disabled={isProcessing || !amount || parseFloat(amount) <= 0}
        onSuccess={handleSuccess}
        onClose={() => toast.error("Payment cancelled")}
        metadata={{
          type: "TOPUP",
          amount: parseFloat(amount),
          userId: userId
        }}
      />
    </div>
  );
}

