export default async function DashboardPage() {
  const session = await getServerSession(authOptions);

  if (!session) {
    redirect("/login");
  }

  const [user, completedCount, pendingWithdrawals, earningsData, recentOrders, totalOrdersCount] = await Promise.all([
    prisma.user.findUnique({
      where: { id: (session.user as any).id },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        balance: true,
        commissionBalance: true,
        agentExpiry: true,
        storeSlug: true
      }
    }),

    prisma.order.count({
      where: {
        OR: [
          { userId: (session.user as any).id },
          { agentId: (session.user as any).id }
        ],
        status: { in: ["PROCESSING", "COMPLETED"] }
      }
    }),
    prisma.withdrawal.aggregate({
      where: { userId: (session.user as any).id, status: "PENDING" },
      _sum: { amount: true }
    }),
    prisma.order.aggregate({
      where: { agentId: (session.user as any).id, status: { in: ["PROCESSING", "COMPLETED"] } },
      _sum: { commissionEarned: true }
    }),
    prisma.order.findMany({
      where: {
        OR: [
          { userId: (session.user as any).id },
          { agentId: (session.user as any).id }
        ]
      },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: {
        id: true,
        status: true,
        phone: true,
        amount: true,
        createdAt: true,
        supplierStatus: true,
        bundle: {
          select: {
            network: true,
            size: true
          }
        }
      }
    }),
    prisma.order.count({
      where: {
        OR: [
          { userId: (session.user as any).id },
          { agentId: (session.user as any).id }
        ]
      }
    })
  ]);

  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);

