"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

import { Session } from "next-auth";

interface AuthUser {
  id: string;
  role: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
}

interface AuthSession extends Session {
  user: AuthUser;
}

async function ensureAgent(): Promise<AuthSession> {
  const session = await getServerSession(authOptions) as AuthSession | null;
  if (!session || (session.user.role !== "AGENT" && session.user.role !== "ADMIN")) {
    throw new Error("Unauthorized");
  }
  return session;
}

export async function getAgentCustomPrices() {
  const session = await ensureAgent();
  const userId = session.user.id;

  return await prisma.agentBundlePrice.findMany({
    where: { agentId: userId }
  });
}

export async function updateAgentStorePrice(bundleId: string, customPrice: number) {
  try {
    const session = await ensureAgent();
    const userId = session.user.id;

    // Verify bundle exists
    const bundle = await prisma.bundle.findUnique({
      where: { id: bundleId }
    });

    if (!bundle) throw new Error("Bundle not found");

    // Prevent pricing below cost (agentPrice)
    if (customPrice < Number(bundle.agentPrice)) {
      throw new Error(`Price cannot be lower than your wholesale cost (GHS ${bundle.agentPrice})`);
    }

    await prisma.agentBundlePrice.upsert({
      where: {
        agentId_bundleId: {
          agentId: userId,
          bundleId: bundleId
        }
      },
      update: { customPrice },
      create: {
        agentId: userId,
        bundleId,
        customPrice
      }
    });

    // Check if user has a store slug, if not, generate one
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { storeSlug: true, name: true }
    });

    let slug = user?.storeSlug;
    if (!slug) {
        const baseName = user?.name || "store";
        const randomStr = Math.floor(1000 + Math.random() * 9000).toString();
        slug = baseName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') + "-" + randomStr;
        
        await prisma.user.update({
            where: { id: userId },
            data: { storeSlug: slug }
        });
    }

    revalidatePath("/dashboard/store");
    if (slug) {
        revalidatePath(`/store/${slug}`);
    }
    return { success: true, slug: slug };
  } catch (error) {
    console.error("Update custom price error:", error);
    return { success: false, error: error instanceof Error ? error.message : "Failed to update price" };
  }
}

export async function resetAgentStorePrice(bundleId: string) {
  try {
    const session = await ensureAgent();
    const userId = session.user.id;

    await prisma.agentBundlePrice.delete({
      where: {
        agentId_bundleId: {
          agentId: userId,
          bundleId: bundleId
        }
      }
    });

    const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { storeSlug: true }
    });

    revalidatePath("/dashboard/store");
    if (user?.storeSlug) {
        revalidatePath(`/store/${user.storeSlug}`);
    }
    return { success: true };
  } catch (error) {
    return { success: false, error: "Failed to reset price" };
  }
}

export async function updateStoreSlug(slug: string) {
    try {
        const session = await ensureAgent();
        const userId = session.user.id;

        // Basic validation
        if (!slug || slug.length < 3) {
            throw new Error("Store name must be at least 3 characters long");
        }

        // Format slug: lowercase, no spaces
        const formattedSlug = slug.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');

        if (!formattedSlug) {
            throw new Error("Invalid store name. Use letters and numbers only.");
        }

        // Check if slug is taken
        const existing = await prisma.user.findFirst({
            where: { 
                storeSlug: formattedSlug,
                id: { not: userId }
            }
        });

        if (existing) {
            throw new Error("This store name is already taken. Please try another.");
        }

        await prisma.user.update({
            where: { id: userId },
            data: { storeSlug: formattedSlug }
        });

        revalidatePath("/dashboard/store");
        return { success: true, slug: formattedSlug };
    } catch (error) {
        return { success: false, error: error instanceof Error ? error.message : "Failed to update store name" };
    }
}

"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";
import { sendPushNotification } from "@/lib/notifications";

export async function topUpWallet(paymentRef: string) {
  const session = await getServerSession(authOptions);

  if (!session) {
    return { success: false, error: "Unauthorized" };
  }

  try {
    // Moolre processes the actual credit via Webhook securely.
    // We poll the DB briefly to see if the webhook already fired, 
    // to give the user immediate feedback if possible.
    
    let attempts = 0;
    let existingTx = null;

    while (attempts < 3) {
      existingTx = await prisma.walletTransaction.findUnique({
        where: { reference: paymentRef }
      });

      if (existingTx) break;
      
      await new Promise(resolve => setTimeout(resolve, 1500));
      attempts++;
    }

    if (existingTx) {
      return { success: true, amount: Number(existingTx.amount), alreadyProcessed: true };
    }

    // If webhook hasn't fired yet, still return success to the client
    // so it can show a pending message or simply wait.

    revalidatePath("/dashboard");
    return { success: true, amount: 0 };

  } catch (error) {
    console.error("Topup error:", error);
    return { success: false, error: "Internal error during top-up" };
  }
}

"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function transferEarningsToWallet(amount: number) {
  const session = await getServerSession(authOptions);
  if (!session) return { success: false, error: "Unauthorized" };

  const userId = (session.user as any).id;

  try {
    if (amount <= 0) throw new Error("Invalid amount");

    await prisma.$transaction(async (tx) => {
      const user = await tx.user.findUnique({
        where: { id: userId },
        select: { commissionBalance: true }
      });

      if (!user || Number(user.commissionBalance) < amount) {
        throw new Error("Insufficient earnings balance");
      }

      // 1. Deduct from earnings
      await tx.user.update({
        where: { id: userId },
        data: { commissionBalance: { decrement: amount } }
      });

      // 2. Add to wallet balance
      await tx.user.update({
        where: { id: userId },
        data: { balance: { increment: amount } }
      });

      // 3. Log transaction
      await tx.walletTransaction.create({
          data: {
              userId,
              amount,
              type: "TOPUP",
              reference: `TRANSFER-${Date.now()}`,
              description: `Earnings transfer to main wallet`
          }
      });
    });

    revalidatePath("/dashboard");
    return { success: true };

  } catch (error: any) {
    console.error("Transfer error:", error);
    return { success: false, error: error.message || "An error occurred" };
  }
}

"use server";

import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function requestWithdrawal(amount: number, phone: string, source: "WALLET" | "COMMISSION" = "WALLET") {
  const session = await getServerSession(authOptions);
  if (!session) return { success: false, error: "Unauthorized" };

  const userId = (session.user as any).id;

  // Restriction: Store earnings (COMMISSION) can only be withdrawn on Fridays
  if (source === "COMMISSION") {
    const today = new Date().getDay(); // 0: Sunday, 1: Monday, ..., 5: Friday, 6: Saturday
    if (today !== 5) {
      return { success: false, error: "Store earnings can only be withdrawn on Fridays" };
    }
  }

  try {
    const result = await prisma.$transaction(async (tx) => {
      const user = await tx.user.findUnique({
        where: { id: userId },
        select: { balance: true, commissionBalance: true }
      });

      if (!user) throw new Error("User not found");

      const currentBalance = source === "COMMISSION" ? Number(user.commissionBalance) : Number(user.balance);

      if (currentBalance < amount) {
        throw new Error(`Insufficient ${source === "COMMISSION" ? "earnings" : "wallet"} balance for withdrawal`);
      }

      // Deduct from correct balance
      await tx.user.update({
        where: { id: userId },
        data: source === "COMMISSION" 
            ? { commissionBalance: { decrement: amount } }
            : { balance: { decrement: amount } }
      });

      // Create withdrawal request
      const wdl = await tx.withdrawal.create({
        data: {
          userId,
          amount,
          phone,
          status: "PENDING"
        }
      });

      // Record transaction
      await tx.walletTransaction.create({
          data: {
              userId,
              amount,
              type: "DEBIT",
              reference: `WDL-REQ-${wdl.id}`,
              description: `Withdrawal request initiated to ${phone}`
          }
      });

      return wdl;
    });

    revalidatePath("/dashboard");
    return { success: true, withdrawalId: result.id };

  } catch (error: any) {
    console.error("Withdrawal error:", error);
    return { success: false, error: error.message || "An error occurred" };
  }
}

export async function transferCommissionToWallet(amount: number) {
    const session = await getServerSession(authOptions);
    if (!session) return { success: false, error: "Unauthorized" };
  
    const userId = (session.user as any).id;
  
    if (amount <= 0) return { success: false, error: "Invalid amount" };
  
    try {
      await prisma.$transaction(async (tx) => {
        const user = await tx.user.findUnique({
          where: { id: userId },
          select: { commissionBalance: true }
        });
  
        if (!user) throw new Error("User not found");
        if (Number(user.commissionBalance) < amount) {
          throw new Error("Insufficient earnings for transfer");
        }
  
        // Move funds
        await tx.user.update({
          where: { id: userId },
          data: {
            commissionBalance: { decrement: amount },
            balance: { increment: amount }
          }
        });
  
        // Record log
        await tx.walletTransaction.create({
            data: {
                userId,
                amount,
                type: "CREDIT",
                reference: `XFER-${Date.now()}`,
                description: `Transferred earnings to main wallet`
            }
        });
      });
  
      revalidatePath("/dashboard");
      return { success: true };
    } catch (error: any) {
      return { success: false, error: error.message || "Transfer failed" };
    }
}

