export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const settings = await getSystemSettings();
  const session = await getServerSession(authOptions);
  const headerList = await headers();
  const pathname = headerList.get("x-pathname") || "";

  const isMaintenanceMode = settings["MAINTENANCE_MODE"] === "true";
  const isAdmin = (session?.user as any)?.role === "ADMIN";
  const isAuthRoute = pathname === "/login" || pathname === "/register";
  const isAdminRoute = pathname.startsWith("/admin");
  const isApiRoute = pathname.startsWith("/api");
  const isStorePage = pathname.startsWith("/store/");

  const showMaintenance = isMaintenanceMode && !isAdmin && !isAdminRoute && !isAuthRoute && !isApiRoute;

  const supportNumber = settings["SUPPORT_WHATSAPP"] || "233540000000";


  return (
    <html lang="en" className="light">
      <body className={`font-sans antialiased min-h-screen flex flex-col`}>
        <Providers>
          {showMaintenance ? (
            <Maintenance supportNumber={supportNumber} />
          ) : (
            <>
              <Navbar />
              <main className="flex-grow pb-24 md:pb-12 overflow-x-hidden">
                {children}
              </main>
              <Footer />
              <BottomNav />
              {!isStorePage && (
                <FloatingWhatsApp 
                    number={supportNumber} 
                    channelUrl={settings["WHATSAPP_CHANNEL_URL"] || ""} 
                />
              )}
            </>
          )}
          <Toaster position="top-center" />
          <OneSignalInit appId={settings["NEXT_PUBLIC_ONESIGNAL_APP_ID"] || ""} />
          <PWAInit />
          <AnnouncementPopup 
            enabled={settings["POPUP_ENABLED"] || "false"} 
            title={settings["POPUP_TITLE"] || "Announcement"} 
            message={settings["POPUP_MESSAGE"] || ""} 
          />
        </Providers>


      </body>
    </html>
  );
}

"use client";

import { useState, Suspense } from "react";
import { signIn } from "next-auth/react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { toast } from "react-hot-toast";

function LoginForm() {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });
  const [loading, setLoading] = useState(false);
  const router = useRouter();
  const searchParams = useSearchParams();
  const callbackUrl = searchParams.get("callbackUrl") || "/dashboard";

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const result = await signIn("credentials", {
        redirect: false,
        email: formData.email,
        password: formData.password,
      });

      if (result?.error) {
        toast.error("Invalid email or password");
      } else {
        toast.success("Logged in successfully!");
        router.push(callbackUrl);
        router.refresh();
      }
    } catch (error) {
      toast.error("An error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md space-y-8 glass p-8 rounded-2xl shadow-xl animate-in">
      <div className="text-center">
        <Link href="/" className="inline-block mb-6 group">
            <span className="text-4xl font-black tracking-tighter text-primary font-outfit group-hover:scale-105 transition-transform block">
                JEI<span className="text-foreground">LINKS</span>
            </span>
        </Link>
        <h2 className="text-3xl font-bold tracking-tight font-outfit">Welcome back</h2>
        <p className="mt-2 text-sm text-muted-foreground">
          Sign in to your account
        </p>
      </div>
      <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
        <div className="space-y-4 rounded-md shadow-sm">
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-foreground">
              Email address
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autoComplete="email"
              required
              className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-foreground shadow-sm focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary sm:text-sm"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            />
          </div>
          <div>
            <div className="flex items-center justify-between mt-1">
               <label htmlFor="password" className="block text-sm font-medium text-foreground">
                 Password
               </label>
               <Link href="/forgot-password" className="text-xs font-bold text-primary hover:underline">
                 Forgot Password?
               </Link>
            </div>
            <input
              id="password"
              name="password"
              type="password"
              autoComplete="current-password"
              required
              className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-foreground shadow-sm focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary sm:text-sm"
              value={formData.password}
              onChange={(e) => setFormData({ ...formData, password: e.target.value })}
            />
          </div>
        </div>

        <div>
          <button
            type="submit"
            disabled={loading}
            className="group relative flex w-full justify-center rounded-md bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground hover:bg-primary/90 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary disabled:opacity-50 transition-all shadow-lg shadow-primary/20"
          >
            {loading ? "Signing in..." : "Log in"}
          </button>
        </div>

        <div className="relative">
          <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t border-border"></span>
          </div>
          <div className="relative flex justify-center text-xs uppercase">
            <span className="bg-background px-2 text-muted-foreground font-bold tracking-widest">Or continue with</span>
          </div>
        </div>

        <button
          type="button"
          onClick={() => signIn("google", { callbackUrl })}
          className="flex w-full justify-center items-center space-x-2 rounded-xl border border-border bg-background px-3 py-2.5 text-sm font-bold text-foreground shadow-sm hover:bg-muted transition-all active:scale-95"
        >
          <svg className="h-5 w-5" viewBox="0 0 24 24">
            <path
              d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              fill="#4285F4"
            />
            <path
              d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              fill="#34A853"
            />
            <path
              d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"
              fill="#FBBC05"
            />
            <path
              d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              fill="#EA4335"
            />
          </svg>
          <span>Continue with Google</span>
        </button>

        <div className="text-center text-sm">
          <span className="text-muted-foreground">Don't have an account? </span>
          <Link href="/register" className="font-medium text-primary hover:text-primary/80">
            Register now
          </Link>
        </div>
      </form>
    </div>
  );
}

export default function LoginPage() {
  return (
    <div className="flex min-h-[calc(100vh-64px)] items-center justify-center bg-background px-4">
      <Suspense fallback={<div className="w-full max-w-md p-8 text-center text-muted-foreground">Loading...</div>}>
        <LoginForm />
      </Suspense>
    </div>
  );
}

import prisma from "@/lib/prisma";
import type { Bundle } from "@prisma/client";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
export const dynamic = "force-dynamic";

import { BundleTabs } from "@/components/BundleTabs";
import { Zap, ShieldCheck, Clock, Wallet, ArrowRight, History, CheckCircle2, RotateCcw, AlertCircle, Users, Package } from "lucide-react";
import { Metadata } from "next";
import Link from "next/link";
import Image from "next/image";
import { formatCurrency, cn } from "@/lib/utils";
import { TopUpButton } from "./dashboard/TopUpButton";
import { RefreshOrderButton } from "@/components/RefreshOrderButton";
import { getActiveSupplier } from "@/lib/suppliers";
import { AdminSupplierBalance } from "@/components/AdminStatsLoader";
import { DollarSign } from "lucide-react";
import { getNetworkSettings, filterBundlesByNetwork } from "@/lib/networkSettings";


export const metadata: Metadata = {
  title: "JEILINKS - Ghana's Fastest Data Top-up Platform",
  description: "Buy MTN, Telecel, and AirtelTigo data bundles instantly at wholesale prices. Become an agent and start earning today.",
};

export default async function Home() {
  const session = await getServerSession(authOptions);
  
  // LOGGED IN VIEW
  if (session) {
    let user = null;
    try {
      user = await prisma.user.findUnique({
        where: { id: (session.user as any).id },
        include: {
          orders: {
            orderBy: { createdAt: "desc" },
            take: 3,
            include: { bundle: true }
          }
        }
      });
    } catch (err) {
      console.error("Home page user fetch error:", err);
    }

    if (!user) return null;
    
    // Calculate Admin Stats if needed
    let todayOrdersCount = 0;
    let todayProfit = 0;
    if (user.role === "ADMIN") {
        const startOfToday = new Date();
        startOfToday.setHours(0, 0, 0, 0);

        const [ordersCount, todayOrders] = await Promise.all([
            prisma.order.count({ where: { createdAt: { gte: startOfToday } } }),
            prisma.order.findMany({
                where: { 
                    createdAt: { gte: startOfToday },
                    status: "COMPLETED"
                },
                include: { bundle: true }
            })
        ]);
        todayOrdersCount = ordersCount;
        todayProfit = todayOrders.reduce((acc, curr) => acc + (Number(curr.amount) - Number(curr.bundle.supplierPrice || 0)), 0);
    }

    const statusIcons: Record<string, any> = {
        PENDING: { color: "text-yellow-500 bg-yellow-100", icon: Clock },
        PROCESSING: { color: "text-blue-500 bg-blue-100", icon: RotateCcw },
        COMPLETED: { color: "text-green-500 bg-green-100", icon: CheckCircle2 },
        FAILED: { color: "text-red-500 bg-red-100", icon: AlertCircle },
    };

    return (
      <div className="flex flex-col min-h-screen animate-in fade-in duration-700">
        <section className="relative py-12 md:py-20 px-4 bg-gradient-to-br from-primary/10 via-background to-background overflow-hidden">
            <div className="absolute top-0 right-0 w-96 h-96 bg-primary/10 rounded-full blur-3xl -z-10" />
            
            <div className="max-w-4xl mx-auto space-y-8">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-black font-outfit">Hi, {(user.name || "User").split(' ')[0]} 👋</h1>
                        <p className="text-muted-foreground">What would you like to do today?</p>
                    </div>
                    <div className="hidden sm:block">
                        <span className="px-3 py-1 bg-primary/10 text-primary rounded-full text-xs font-black uppercase tracking-widest border border-primary/20">
                            {user.role} Account
                        </span>
                    </div>
                </div>

                {/* ADMIN STATS BAR */}
                {user.role === "ADMIN" && (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4 pb-4">
                        {/* Today's Orders */}
                        <Link href="/admin/orders" className="glass p-4 md:p-5 rounded-2xl md:rounded-3xl border border-border shadow-lg flex items-center justify-between group hover:border-primary/30 transition-all">
                            <div className="flex items-center space-x-3 md:space-x-4">
                                <div className="p-2 md:p-3 bg-primary/10 rounded-xl md:rounded-2xl text-primary group-hover:scale-110 transition-transform">
                                    <Package className="h-4 w-4 md:h-5 md:w-5" />
                                </div>
                                <div className="min-w-0">
                                    <p className="text-[10px] md:text-[10px] font-black uppercase tracking-widest text-muted-foreground truncate">Orders Today</p>
                                    <h3 className="text-lg md:text-xl font-black font-outfit tracking-tighter truncate">
                                        {todayOrdersCount.toLocaleString()}
                                    </h3>
                                </div>
                            </div>
                            <ArrowRight className="h-4 w-4 text-muted-foreground opacity-50 group-hover:translate-x-1 transition-all" />
                        </Link>

                        {/* Today's Profit */}
                        <div className="glass p-4 md:p-5 rounded-2xl md:rounded-3xl border border-emerald-500/20 bg-emerald-50/5 shadow-lg flex items-center justify-between group hover:border-emerald-500/40 transition-all">
                            <div className="flex items-center space-x-3 md:space-x-4">
                                <div className="p-2 md:p-3 bg-emerald-500/10 rounded-xl md:rounded-2xl text-emerald-600 group-hover:scale-110 transition-transform">
