"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { RefreshCcw, Pause, Play } from "lucide-react";

export function AutoRefreshToggle() {
    const [isEnabled, setIsEnabled] = useState(false);
    const [timeLeft, setTimeLeft] = useState(60);
    const router = useRouter();

    useEffect(() => {
        if (!isEnabled) {
            setTimeLeft(60);
            return;
        }

        const interval = setInterval(() => {
            setTimeLeft((prev) => prev - 1);
        }, 1000);

        return () => clearInterval(interval);
    }, [isEnabled]);

    useEffect(() => {
        if (isEnabled && timeLeft <= 0) {
            router.refresh();
            setTimeLeft(60);
        }
    }, [isEnabled, timeLeft, router]);

    const percentage = (timeLeft / 60) * 100;

    return (
        <div className="flex items-center space-x-3 bg-white dark:bg-zinc-950 px-3.5 py-2 rounded-2xl border shadow-sm transition-all hover:shadow-md group">
            <div className="relative flex items-center justify-center w-10 h-10">
                <svg className="w-10 h-10 transform -rotate-90">
                    <circle
                        cx="20"
                        cy="20"
                        r="18"
                        stroke="currentColor"
                        strokeWidth="2.5"
                        fill="transparent"
                        className="text-secondary"
                    />
                    {isEnabled && (
                        <circle
                            cx="20"
                            cy="20"
                            r="18"
                            stroke="currentColor"
                            strokeWidth="2.5"
                            fill="transparent"
                            strokeDasharray={113.1}
                            strokeDashoffset={113.1 - (113.1 * percentage) / 100}
                            className="text-primary transition-all duration-1000 ease-linear"
                            strokeLinecap="round"
                        />
                    )}
                </svg>
                <button 
                    onClick={() => setIsEnabled(!isEnabled)}
                    className={`absolute inset-0 flex items-center justify-center rounded-full transition-all ${isEnabled ? "text-primary" : "text-muted-foreground group-hover:text-foreground"}`}
                >
                    {isEnabled ? <Pause className="h-4 w-4 fill-current" /> : <Play className="h-4 w-4 ml-0.5 fill-current" />}
                </button>
            </div>

            <div className="flex flex-col min-w-[70px]">
                <span className="text-[9px] font-black uppercase tracking-[0.15em] text-muted-foreground/80 leading-none mb-1">Status Sync</span>
                <div className="flex items-center space-x-2">
                    <span className="text-xs font-black font-mono tracking-tighter">
                        {isEnabled ? `${timeLeft}s` : "DISABLED"}
                    </span>
                    {isEnabled && <RefreshCcw className="h-2.5 w-2.5 text-primary animate-spin" />}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useSession } from "next-auth/react";
import { formatCurrency } from "@/lib/utils";
import { Smartphone, Zap } from "lucide-react";
import { toast } from "react-hot-toast";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import PaystackButton from "./PaystackButton";

interface BundleCardProps {
  bundle: {
    id: string;
    network: string;
    size: string;
    userPrice: number;
    agentPrice: number;
  };
  agentId?: string;
}

export function BundleCard({ bundle, agentId }: BundleCardProps) {
  const { data: session } = useSession();
  const router = useRouter();
  const [phoneNumber, setPhoneNumber] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showPrompt, setShowPrompt] = useState(false);

  const role = (session?.user as any)?.role || "USER";
  const price = (role === "AGENT" || role === "ADMIN") ? bundle.agentPrice : bundle.userPrice;


  const networkColors: Record<string, string> = {
    MTN: "bg-mtn text-black",
    Telecel: "bg-telecel text-white",
    AirtelTigo: "bg-airteltigo text-white",
  };

  const handleSuccess = (reference: any) => {
    handleOrderCreation(reference.reference);
  };

  const handleOrderCreation = async (paystackRef: string) => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bundleId: bundle.id,
          phone: phoneNumber,
          paymentRef: paystackRef,
          amount: price,
          agentId: agentId || null,
        }),
      });

      if (res.ok) {
        const orderData = await res.json();
        toast.promise(
          new Promise((resolve) => setTimeout(resolve, 2000)),
          {
            loading: 'Confirming payment...',
            success: 'Order placed successfully!',
            error: 'Failed to place order',
          }
        );
        
        if (session) {
          router.push("/dashboard");
        } else {
          router.push(`/track?ref=${orderData.id}`);
        }
      } else {
        toast.error("Failed to create order. Please contact support.");
      }
    } catch (error) {
      toast.error("An error occurred");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePay = () => {
    if (!session) {
      toast.error("Please login to purchase");
      router.push("/login?callbackUrl=/");
      return;
    }

    if (!showPrompt) {
        setShowPrompt(true);
        return;
    }

    const ghPhoneRegex = /^(02|05)\d{8}$/;
    if (!phoneNumber || !ghPhoneRegex.test(phoneNumber.replace(/\s/g, ""))) {
      toast.error("Please enter a valid Ghanaian phone number (e.g. 024XXXXXXX or 054XXXXXXX)");
      return;
    }
  };

  return (
    <div className="group relative flex flex-col h-full justify-between overflow-hidden rounded-2xl bg-card p-6 shadow-md transition-all hover:shadow-xl hover:-translate-y-1 border border-border/50">
      <div>
        <div className={`absolute top-0 right-0 px-4 py-1 rounded-bl-xl text-xs font-bold uppercase tracking-wider ${networkColors[bundle.network] || 'bg-primary text-white'}`}>
          {bundle.network}
        </div>
        
        <div className="flex items-center space-x-4 mb-4">
          <div className={`p-3 rounded-xl ${networkColors[bundle.network] || 'bg-primary text-white'} opacity-90`}>
            <Smartphone className="h-6 w-6" />
          </div>
          <div>
            <h3 className="text-xl font-bold font-outfit">{bundle.size}</h3>
            <p className="text-sm text-muted-foreground">Mobile Data Bundle</p>
          </div>
        </div>
      </div>

      <div className="space-y-4 mt-auto">
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">Price</span>
          <span className="text-2xl font-bold text-primary font-outfit">{formatCurrency(price)}</span>
        </div>

        {showPrompt && (
          <div className="space-y-2 animate-in slide-in-from-top duration-300">
            <label className="text-xs font-medium text-muted-foreground flex justify-between">
                <span>Recipient Number</span>
                <button onClick={() => setShowPrompt(false)} className="text-[10px] underline">Back</button>
            </label>
            <input
              type="tel"
              placeholder="054XXXXXXX"
              value={phoneNumber}
              autoFocus
              onChange={(e) => setPhoneNumber(e.target.value)}
              className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-primary shadow-inner"
            />
          </div>
        )}

        {showPrompt ? (
          <div className="pt-2">
            <PaystackButton
              email={session?.user?.email || "guest@jeilinks.com"}
              amount={price}
              label={isLoading ? "Processing..." : "Confirm & Pay"}
              className="w-full bg-primary text-primary-foreground py-3 rounded-2xl font-bold font-outfit shadow-lg shadow-primary/20 hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
              disabled={!phoneNumber || isLoading}
              onSuccess={handleSuccess}
              onClose={() => toast.error("Payment cancelled")}
              metadata={{
                type: "BUNDLE_PURCHASE",
                bundleId: bundle.id,
                phone: phoneNumber,
                agentId: agentId || null,
                userId: session?.user ? (session.user as any).id : null
              }}
            />
          </div>
        ) : (
          <button
            onClick={handlePay}
            className="w-full flex items-center justify-center space-x-2 rounded-xl py-3 text-sm font-bold transition-all shadow-lg shadow-primary/20 bg-primary text-primary-foreground hover:brightness-110 active:scale-95"
          >
            <Zap className="h-4 w-4" />
            <span>Buy Now</span>
          </button>
        )}
        
        {(role === "AGENT" || role === "ADMIN") && (
          <div className="mt-4 pt-4 border-t border-dashed text-center">
            <p className="text-[10px] text-green-500 font-bold uppercase tracking-tighter">{role === "ADMIN" ? "Admin" : "Agent"} Wholesale Pricing Applied</p>
          </div>
        )}

      </div>
    </div>
  );
}

