"use client";

import { useEffect, useState } from "react";
import { Bell, BellOff } from "lucide-react";
import toast from "react-hot-toast";
import { cn } from "@/lib/utils";

export default function NotificationBell() {
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isSupported, setIsSupported] = useState(false);

  useEffect(() => {
    if (typeof window !== "undefined") {
      window.OneSignal = window.OneSignal || [];
      
      const checkSubscription = async () => {
        const state = await window.OneSignal.getNotificationPermission();
        setIsSubscribed(state === "granted");
        setIsSupported(window.OneSignal.isPushNotificationsSupported());
      };

      window.OneSignal.push(() => {
        checkSubscription();
        window.OneSignal.on('notificationPermissionChange', (permissionChange: any) => {
          setIsSubscribed(permissionChange.to === "granted");
        });
      });
    }
  }, []);

  const handleToggle = () => {
    if (!isSupported) {
      toast.error("Push notifications are not supported on this browser.");
      return;
    }

    if (isSubscribed) {
      toast.success("You are already subscribed to notifications!");
    } else {
      window.OneSignal.push(() => {
        window.OneSignal.showNativePrompt();
      });
    }
  };

  // Always render the bell for a 'fixed' look, but handle unsupported state
  const isAvailable = isSupported && typeof window !== "undefined" && window.OneSignal;

  return (
    <button
      onClick={handleToggle}
      disabled={!isAvailable}
      className={cn(
        "relative p-2 rounded-full transition-all active:scale-95",
        !isAvailable ? "opacity-40 grayscale cursor-not-allowed" : "hover:scale-110",
        isAvailable && isSubscribed 
          ? "bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400" 
          : isAvailable ? "bg-primary/10 text-primary animate-pulse" : "bg-muted text-muted-foreground"
      )}
      title={!isAvailable ? "Notifications not supported" : isSubscribed ? "Notifications Active" : "Enable Notifications"}
    >
      {isSubscribed && isAvailable ? (
        <Bell className="h-5 w-5" />
      ) : (
        <BellOff className="h-5 w-5" />
      )}
      {isAvailable && !isSubscribed && (
        <span className="absolute top-1 right-1 h-2 w-2 bg-red-500 rounded-full border-2 border-white dark:border-slate-900" />
      )}
    </button>
  );
}

"use client";

import { useEffect } from "react";
import { useSession } from "next-auth/react";

declare global {
  interface Window {
    OneSignal: any;
  }
}

export default function OneSignalInit({ appId }: { appId: string }) {
  const { data: session } = useSession();

  useEffect(() => {
    if (typeof window !== "undefined" && appId) {
      window.OneSignal = window.OneSignal || [];
      window.OneSignal.push(function() {
        window.OneSignal.init({
          appId: appId,
          safari_web_id: undefined, // Optional: only if you have Safari Web ID
          notifyButton: {
            enable: false,
          },
          allowLocalhostAsSecureOrigin: true,
        });

        // Set external ID if user is logged in
        const userId = (session?.user as any)?.id;
        if (userId) {
          window.OneSignal.setExternalUserId(userId);
          
          // Get player ID and register it
          window.OneSignal.getUserId().then((playerId: string) => {
            if (playerId) {
              fetch("/api/notifications/register", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ playerId }),
              });
            }
          });
        }
      });

      const script = document.createElement("script");
      script.src = "https://cdn.onesignal.com/sdks/OneSignalSDK.js";
      script.async = true;
      document.head.appendChild(script);

      return () => {
        // Optional: cleanup if needed
      };
    }
  }, [appId, session]);

  return null;
}

"use client";

import { useEffect, useState } from "react";
import { X, Download, Smartphone, Share, PlusSquare } from "lucide-react";
import { useKeyboardVisible } from "@/hooks/useKeyboardVisible";

export default function PWAInit() {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showBanner, setShowBanner] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [isStandalone, setIsStandalone] = useState(false);
  const isKeyboardVisible = useKeyboardVisible();

  useEffect(() => {
    // 1. Check if already installed
    const standalone = (window.navigator as any).standalone || window.matchMedia('(display-mode: standalone)').matches;
    setIsStandalone(standalone);

    // 2. Detect iOS
    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    // 3. Register Service Worker
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('/sw.js').then((reg) => {
        console.log('SW Registered', reg);
      });
    }

    // 4. Handle the Before Install Prompt (Android/Chrome)
    const handler = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      if (!standalone) {
        setShowBanner(true);
      }
    };

    window.addEventListener('beforeinstallprompt', handler);

    // 5. For iOS, show banner if not standalone
    if (ios && !standalone) {
      const hasDismissed = localStorage.getItem('pwa-banner-dismissed');
      if (!hasDismissed) {
        setShowBanner(true);
      }
    }

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstall = async () => {
    if (isIOS) {
      // For iOS, we just show instructions (the banner itself changes state or we can use an alert)
      return;
    }

    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    console.log(`User response to the install prompt: ${outcome}`);
    setDeferredPrompt(null);
    setShowBanner(false);
  };

  const dismissBanner = () => {
    setShowBanner(false);
    if (isIOS) {
      localStorage.setItem('pwa-banner-dismissed', 'true');
    }
  };

  if (!showBanner || isStandalone || isKeyboardVisible) return null;

  return (
    <div className="fixed bottom-24 left-4 right-4 z-[100] animate-in slide-in-from-bottom-10 fade-in duration-700">
      <div className="relative overflow-hidden bg-slate-900/90 text-white p-5 rounded-[2rem] shadow-2xl border border-white/20 backdrop-blur-2xl">
        {/* Decorative background glow */}
        <div className="absolute -top-10 -right-10 w-32 h-32 bg-primary/20 rounded-full blur-3xl pointer-events-none" />

        <div className="relative flex flex-col space-y-4">
          <div className="flex items-start justify-between">
            <div className="flex items-center space-x-4">
              <div className="bg-gradient-to-br from-primary to-blue-600 p-3 rounded-2xl shadow-lg shadow-primary/20">
                <Smartphone className="h-6 w-6 text-white" />
              </div>
              <div>
                <h3 className="font-bold text-base tracking-tight">Install JEILINKS App</h3>
                <p className="text-xs text-slate-400 font-medium">Fast access & better experience</p>
              </div>
            </div>
            <button 
              onClick={dismissBanner}
              className="p-2 -mr-2 text-slate-400 hover:text-white transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          {isIOS ? (
            <div className="bg-white/5 rounded-2xl p-4 border border-white/10 space-y-3">
              <p className="text-[11px] text-slate-300 leading-relaxed">
                To install, tap the <span className="inline-flex items-center px-1.5 py-0.5 bg-white/10 rounded-md mx-0.5"><Share className="h-3 w-3 inline" /></span> icon in Safari and select <span className="font-bold text-white uppercase tracking-wider mx-1 text-[10px]">"Add to Home Screen"</span>
              </p>
              <div className="flex justify-center pt-1">
                <div className="animate-bounce">
                    <PlusSquare className="h-5 w-5 text-primary" />
                </div>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-end pt-1">
              <button 
                onClick={handleInstall}
                className="w-full bg-primary hover:bg-blue-600 text-white py-3 rounded-2xl text-sm font-black transition-all active:scale-[0.98] shadow-xl shadow-primary/30 flex items-center justify-center space-x-2 group"
              >
                <Download className="h-4 w-4 group-hover:translate-y-0.5 transition-transform" />
                <span>INSTALL NOW</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

