"use client";

import { useEffect, useState, useMemo } from "react";

interface PaystackButtonInnerProps {
  email: string;
  amount: number;
  onSuccess: (ref: any) => void;
  onClose: () => void;
  label: string;
  className?: string;
  disabled?: boolean;
  metadata?: any;
}

export default function PaystackButtonInner({
  email,
  amount,
  onSuccess,
  onClose,
  label,
  className,
  disabled,
  metadata
}: PaystackButtonInnerProps) {
  const [mounted, setMounted] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const reference = useMemo(() => {
    return `JL-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
  }, []);

  useEffect(() => {
    setMounted(true);
  }, []);

  // When user returns to the tab after redirect, check if payment was successful
  useEffect(() => {
    if (typeof window === "undefined") return;

    const params = new URLSearchParams(window.location.search);
    const trxref = params.get("trxref") || params.get("reference");

    if (trxref) {
      // Remove params from URL cleanly
      const url = new URL(window.location.href);
      url.searchParams.delete("trxref");
      url.searchParams.delete("reference");
      window.history.replaceState({}, "", url.toString());

      // Fire success callback so the parent can handle it
      onSuccess({ reference: trxref });
    }
  }, []);

  const handlePayment = async () => {
    if (isLoading) return;
    setIsLoading(true);

    try {
      const res = await fetch("/api/paystack/initialize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount,
          email,
          externalRef: reference,
          currency: "GHS",
          metadata,
          redirectUrl: window.location.href,
        }),
      });

      const data = await res.json();

      if (!res.ok || !data.paymentUrl) {
        const errMsg = data?.error || "Could not create payment link. Please try again.";
        console.error("[Paystack] Server error:", data);
        alert(`Payment Error: ${errMsg}`);
        setIsLoading(false);
        return;
      }

      console.log("[Paystack] Redirecting to:", data.paymentUrl);
      // Redirect to Paystack's hosted checkout page
      window.location.href = data.paymentUrl;

    } catch (error: any) {
      console.error("[Paystack] Unexpected error:", error);
      alert(`Payment error: ${error?.message || error}`);
      setIsLoading(false);
    }
  };

  if (!mounted) return null;

  return (
    <button
      type="button"
      className={className}
      disabled={disabled || isLoading}
      onClick={handlePayment}
    >
      {isLoading ? "Connecting..." : label}
    </button>
  );
}

import { NextAuthOptions } from "next-auth"
import CredentialsProvider from "next-auth/providers/credentials"
import GoogleProvider from "next-auth/providers/google"
import prisma from "@/lib/prisma"
import { PrismaAdapter } from "@auth/prisma-adapter"
import bcrypt from "bcryptjs"

export const authOptions: NextAuthOptions = {
  adapter: PrismaAdapter(prisma) as any,
  session: {
    strategy: "jwt",
  },
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID || "",
      clientSecret: process.env.GOOGLE_CLIENT_SECRET || "",
    }),
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null

        const user = await prisma.user.findUnique({
          where: { email: credentials.email.toLowerCase() }
        })

        if (!user || !user.password) return null

        const isValid = await bcrypt.compare(credentials.password, user.password)

        if (!isValid) return null

        return {
          id: user.id,
          name: user.name,
          email: user.email,
          role: user.role,
        }
      }
    })
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id
        token.role = (user as any).role
      }
      return token
    },
    async session({ session, token }) {
      if (token && session.user) {
        (session.user as any).id = token.id;
        // M8 FIX: Always pull the live role from DB so:
        // (a) newly upgraded agents see agent pricing without re-logging in, and
        // (b) demoted users lose privileges on the next request.
        try {
          const dbUser = await prisma.user.findUnique({
            where: { id: token.id as string },
            select: { role: true }
          });
          (session.user as any).role = dbUser?.role ?? token.role;
        } catch {
          // Fallback to token role if DB is unavailable
          (session.user as any).role = token.role;
        }
      }
      return session
    }
  },
  pages: {
    signIn: "/login",
  },
  secret: process.env.NEXTAUTH_SECRET,
}

import prisma from "./prisma";

export async function getNetworkSettings() {
  const settings = await prisma.systemSetting.findMany({
    where: {
      key: {
        in: [
          'NETWORK_MTN_ENABLED',
          'NETWORK_AIRTELTIGO_ENABLED',
          'NETWORK_TELECEL_ENABLED',
          'NETWORK_GLO_ENABLED',
          'NETWORK_SPECIAL_OFFERS_ENABLED'
        ]
      }
    }
  });

  const getSetting = (k: string) => {
    const s = settings.find(s => s.key === k);
    return s ? s.value === 'true' : true; // Default to true if not set
  };

  const enabledNetworks = {
    "MTN": getSetting('NETWORK_MTN_ENABLED'),
    "AirtelTigo": getSetting('NETWORK_AIRTELTIGO_ENABLED'),
    "Telecel": getSetting('NETWORK_TELECEL_ENABLED'),
    "Glo": getSetting('NETWORK_GLO_ENABLED'),
    "Special Offers": getSetting('NETWORK_SPECIAL_OFFERS_ENABLED')
  };

  return enabledNetworks;
}

export function filterBundlesByNetwork(bundles: any[], networkSettings: Record<string, boolean>) {
  return bundles.filter(b => {
    // If it's one of the known networks, check if it's enabled
    const normalizedNetwork = Object.keys(networkSettings).find(
      key => key.toLowerCase() === b.network.toLowerCase()
    );
    if (normalizedNetwork) {
      return networkSettings[normalizedNetwork];
    }
    // If it's an unknown network, just allow it
    return true;
  });
}

import { FuzeServeProvider } from "./suppliers/fuzeserve";
import { MySocialBoosterProvider } from "./suppliers/mysocialbooster";
import { SupplierProvider } from "./suppliers/types";
import prisma from "@/lib/prisma";

/**
 * Returns the correct supplier instance for a given bundle.
 * Looks up the SupplierMapping table first. If no mapping exists,
 * falls back to the legacy supplierProductId + active SUPPLIER_TYPE setting.
 */
export async function getSupplierForBundle(bundleId: string): Promise<{
  supplier: SupplierProvider;
  supplierProductId: string;
  supplierType: string;
}> {
  // Fetch system settings from DB first so they are available for both mappings and fallbacks
  const settingsList = await prisma.systemSetting.findMany({
    where: { key: { in: ["SUPPLIER_TYPE", "SUPPLIER_API_KEY", "SUPPLIER_API_BASE",
                          "FUZESERVE_API_KEY", "FUZESERVE_API_BASE",
                          "MYSOCIALBOOSTER_API_KEY", "MYSOCIALBOOSTER_API_BASE"] } }
  });
  const settings: Record<string, string> = {};
  settingsList.forEach(s => settings[s.key] = s.value);

  const activeSupplierType = (settings["SUPPLIER_TYPE"] || process.env.SUPPLIER_TYPE || "FUZESERVE").toUpperCase();

  // 1. Check SupplierMapping table for an explicit per-bundle routing matching the active supplier type
  let mapping = await prisma.supplierMapping.findFirst({
    where: { 
      bundleId,
      supplierType: activeSupplierType
    },
  });

  if (!mapping) {
    mapping = await prisma.supplierMapping.findFirst({
      where: { bundleId },
    });
  }

  if (mapping) {
    const supplier = buildSupplier(mapping.supplierType, settings);
    return {
      supplier,
      supplierProductId: mapping.supplierProductId,
      supplierType: mapping.supplierType,
    };
  }

  // 2. Fallback: use the bundle's own supplierProductId + the global active supplier
  const bundle = await prisma.bundle.findUnique({
    where: { id: bundleId },
    select: { supplierProductId: true },
  });

  const type = (settings["SUPPLIER_TYPE"] || process.env.SUPPLIER_TYPE || "FUZESERVE").toUpperCase();

  return {
    supplier: buildSupplier(type, settings),
    supplierProductId: bundle?.supplierProductId || "",
    supplierType: type,
  };
}

/**
 * Instantiates a supplier provider by type name.
 * Reads API credentials from settings (DB-first, then env fallback).
 */
export function buildSupplier(type: string, settings: Record<string, string> = {}): SupplierProvider {
  const apiKey = settings[`${type}_API_KEY`] || settings["SUPPLIER_API_KEY"] || process.env.SUPPLIER_API_KEY || "";
  const apiBase = settings[`${type}_API_BASE`] || settings["SUPPLIER_API_BASE"] || process.env.SUPPLIER_API_BASE || "";

  switch (type.toUpperCase()) {
    case "FUZESERVE":
      return new FuzeServeProvider(apiKey, apiBase);
    case "MYSOCIALBOOSTER":
      return new MySocialBoosterProvider(apiKey, apiBase);
    default:
      return new FuzeServeProvider(apiKey, apiBase);
  }
}

/**
 * Place an order on the correct supplier for a given bundle.
 * This is the main entry point used by the orders route.
 */
export async function placeOrderOnSupplier(order: {
  bundleId: string;
  supplierProductId?: number | string;
  phone: string;
  reference: string;
}) {
  try {
    const { supplier, supplierProductId } = await getSupplierForBundle(order.bundleId);

    const productId = order.supplierProductId || supplierProductId;
    if (!productId) {
      return { success: false, error: "No supplier product ID configured for this bundle" };
    }

    const result = await supplier.placeOrder(productId, order.phone, order.reference);
    return result;
  } catch (err: any) {
    console.error("placeOrderOnSupplier error:", err);
    return { success: false, error: err.message || "Unknown supplier error" };
  }
}

/**
 * Track an order on the correct supplier.
 * Uses the supplierType stored on the order to pick the right provider.
 */
export async function trackOrderOnSupplier(
  supplierOrderId: string,
  supplierType: string
): Promise<any> {
  try {
    const settingsList = await prisma.systemSetting.findMany();
    const settings: Record<string, string> = {};
    settingsList.forEach(s => settings[s.key] = s.value);

    const supplier = buildSupplier(supplierType, settings);
    return await supplier.trackOrder(supplierOrderId);
  } catch (err: any) {
    return { success: false, error: err.message };
  }
}

import { SupplierProvider, StandardProduct, OrderResponse } from "./types";

export class FuzeServeProvider implements SupplierProvider {
  name = "FuzeServe";
  private baseUrl: string;
  private apiKey: string;

  constructor(apiKey?: string, baseUrl?: string) {
    this.apiKey = apiKey || process.env.SUPPLIER_API_KEY || "";
    this.baseUrl = baseUrl || process.env.SUPPLIER_API_BASE || "https://fuzeserve.com/api";
  }

  async fetchProducts(): Promise<StandardProduct[]> {
    if (!this.apiKey) throw new Error("FuzeServe API Key missing");

    // M3 FIX: Add timeout to prevent hanging supplier calls from blocking the function.
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    try {
      const response = await fetch(`${this.baseUrl}/v1/products`, {
        method: "GET",
        headers: {
          "X-API-Key": this.apiKey,
          "Accept": "application/json"
        },
        signal: controller.signal
      });

      if (!response.ok) throw new Error("FuzeServe fetch failed");
      
      const data = await response.json();
      return data.map((p: any) => ({
        id: p.id,
        name: p.name,
        network: p.network,
        size: p.dataAmount,
        price: p.price,
        resellerPrice: p.resellerPrice || p.price
      }));
    } finally {
      clearTimeout(timeout);
    }
  }

  async placeOrder(productId: number | string, phone: string, reference: string): Promise<OrderResponse> {
    // Ensure phone starts with 0 for this specific supplier
    let formattedPhone = phone.replace(/\D/g, "");
    if (formattedPhone.startsWith("233")) {
      formattedPhone = "0" + formattedPhone.substring(3);
    } else if (!formattedPhone.startsWith("0")) {
      formattedPhone = "0" + formattedPhone;
    }

    const url = `${this.baseUrl}/v1/orders`;
    const body = {
      productId: Number(productId),
      phone: formattedPhone,
      externalReference: reference,
    };

    console.log(`FuzeServe Request: POST ${url} phone=${formattedPhone} productId=${productId}`);

    // M3 FIX: 15-second timeout prevents hanging supplier calls from exhausting Vercel function time.
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    try {
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-API-Key": this.apiKey,
        },
        body: JSON.stringify(body),
        signal: controller.signal
      });

      const data = await response.json().catch(() => ({ error: "Invalid JSON response" }));
      console.log(`FuzeServe Response (${response.status}): status=${data?.status}`);

      if (!response.ok) {
        return { 
          success: false, 
          error: data.message || data.error || `HTTP ${response.status}: ${JSON.stringify(data)}`
        };
      }

      return {
        success: true,
        supplierOrderId: data.reference || data.id || data.orderId,
        status: data.status || "PROCESSING"
      };
    } catch (err: any) {
      if (err.name === "AbortError") {
        console.error("FuzeServe request timed out after 15s");
        return { success: false, error: "Supplier request timed out" };
      }
      console.error("FuzeServe fetch error:", err);
      return { success: false, error: `Connection error: ${err.message}` };
    } finally {
      clearTimeout(timeout);
    }
  }

  async trackOrder(supplierOrderId: string): Promise<OrderResponse> {
    // M3 FIX: Timeout prevents slow tracking calls from blocking the cron job.
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    try {
      const response = await fetch(`${this.baseUrl}/v1/orders/${supplierOrderId}`, {
        method: "GET",
        headers: {
          "X-API-Key": this.apiKey,
          "Accept": "application/json"
        },
        signal: controller.signal
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        return { success: false, error: errorData.message || "Tracking failed" };
      }
      
      const data = await response.json();
      return {
        success: true,
        status: data.status?.toUpperCase(),
        error: data.status?.toUpperCase() === "FAILED" ? (data.message || data.reason) : undefined
      };
    } catch (err: any) {
      if (err.name === "AbortError") {
        return { success: false, error: "Supplier tracking request timed out" };
      }
      return { success: false, error: err.message || "Tracking failed" };
    } finally {
      clearTimeout(timeout);
    }
  }

  async fetchBalance(): Promise<number> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);
    try {
      const response = await fetch(`${this.baseUrl}/v1/balance`, {
        method: "GET",
        headers: {
          "X-API-Key": this.apiKey,
          "Accept": "application/json"
        },
        signal: controller.signal
      });

      if (!response.ok) return 0;
      const data = await response.json();
      return data.balance || 0;
    } catch {
      return 0;
    } finally {
      clearTimeout(timeout);
    }
  }
}

import { SupplierProvider, StandardProduct, OrderResponse } from "./types";

export class MySocialBoosterProvider implements SupplierProvider {
  name = "MySocialBooster";
  private apiKey: string;
  private baseUrl: string;

  constructor(apiKey: string, baseUrl: string) {
    this.apiKey = apiKey;
    this.baseUrl = baseUrl.endsWith("/") ? baseUrl.slice(0, -1) : baseUrl;
  }

  private async request(endpoint: string, options: RequestInit = {}) {
    const url = `${this.baseUrl}${endpoint}`;
    // M3 FIX: 15-second timeout prevents hanging supplier API calls.
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    try {
      const response = await fetch(url, {
        ...options,
        headers: {
          "X-API-Key": this.apiKey,
          "Content-Type": "application/json",
          ...options.headers,
        },
        signal: controller.signal,
      });

      if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          throw new Error(errorData.message || `MySocialBooster API error: ${response.statusText}`);
      }

      return response.json();
    } catch (err: any) {
      if (err.name === "AbortError") {
        throw new Error("MySocialBooster API request timed out");
      }
      throw err;
    } finally {
      clearTimeout(timeout);
    }
  }

  async fetchProducts(): Promise<StandardProduct[]> {
    const data = await this.request("/products");
    const products = data.response || [];

    return products.map((p: any) => ({
      id: p.id,
      name: p.name,
      network: this.inferNetwork(p.name),
      size: this.inferSize(p.name),
      price: Number(p.price),
      resellerPrice: Number(p.price), // Tier pricing already handled by supplier
    }));
  }

  async placeOrder(productId: string | number, phone: string, reference: string): Promise<OrderResponse> {
    try {
      const data = await this.request("/orders", {
        method: "POST",
        body: JSON.stringify({
          productId: productId.toString(),
          recipientNumber: phone,
        }),
      });

      // MySocialBooster might return 200 OK but with a success: false in the body
      if (data.success === false || !data.response) {
        return {
          success: false,
          error: data.message || "Supplier returned an empty or failed response",
        };
      }

      const order = data.response;
      return {
        success: true,
        supplierOrderId: (order.id || order.orderId || order.reference || "N/A").toString(),
        status: order.status || "PROCESSING",
      };
    } catch (error: any) {
      return {
        success: false,
        error: error.message,
      };
    }
  }

  async trackOrder(supplierOrderId: string): Promise<OrderResponse> {
    try {
      const data = await this.request(`/orders/${supplierOrderId}`);
      const order = data.response;
      // M7 FIX: Normalize the status so the cron job can correctly identify
      // 'completed' and 'failed' states from this supplier.
      // Without normalization, non-standard statuses like 'DONE' or 'SUCCESS' would
      // never match the cron's 'completed' check, leaving orders stuck in PROCESSING.
      const rawStatus = (order.status || "").toUpperCase();
      let normalizedStatus: string;
      if (["SUCCESS", "COMPLETED", "DELIVERED", "DONE"].includes(rawStatus)) {
        normalizedStatus = "completed";
      } else if (["FAILED", "REJECTED", "CANCELLED", "DECLINED"].includes(rawStatus)) {
        normalizedStatus = "failed";
      } else if (["PROCESSING", "IN_PROGRESS", "SENT"].includes(rawStatus)) {
        normalizedStatus = "processing";
      } else {
        normalizedStatus = rawStatus.toLowerCase();
      }

      return {
        success: true,
        supplierOrderId: order.id,
        status: normalizedStatus,
      };
    } catch (error: any) {
      return {
        success: false,
        error: error.message,
      };
    }
  }

  async fetchBalance(): Promise<number> {
    try {
      const data = await this.request("/wallet/balance");
      return Number(data.response.balance);
    } catch (error) {
      console.error("MySocialBooster fetchBalance error:", error);
      return 0;
    }
  }

  private inferNetwork(name: string): string {
    const n = name.toUpperCase();
    if (n.includes("SPECIAL OFFER")) return "Special Offers";
    if (n.includes("MTN")) return "MTN";
    if (n.includes("VODA") || n.includes("TELECEL")) return "Telecel";
    // "NX AT 2GB", "AIRTELTIGO", "AIRTEL", "TIGO" all map to AirtelTigo
    // Use word-boundary check so standalone "AT" is matched correctly
    if (n.includes("AIRTEL") || n.includes("TIGO") || /\bAT\b/.test(n)) return "AirtelTigo";
    if (n.includes("GLO")) return "Glo";
    return "OTHER";
  }

  private inferSize(name: string): string {
    // Also handle cases like "890. MB" by allowing optional dot before spaces
    const match = name.match(/(\d+(\.\d*)?\s*(GB|MB))/i);
    return match ? match[0].replace('. ', '') : name;
  }
}

import { getActiveSupplier } from "./src/lib/suppliers";

async function testConnection() {
  try {
    const supplier = await getActiveSupplier();
    console.log(`Testing connection to: ${supplier.name}`);
    const balance = await supplier.fetchBalance();
    console.log(`Connection Successful! Balance: ${balance}`);

    console.log("Fetching products...");
    const products = await supplier.fetchProducts();
    console.log(`Found ${products.length} products.`);
    if (products.length > 0) {
        console.log("First product sample:", products[0]);
    }
  } catch (error: any) {
    console.error("Connection Failed!");
    console.error(error.message);
  }
}

testConnection();
